/* Frekvens — tokens. Generado desde tokens.json. */
:root, [data-theme="light"] {
  color-scheme: light;
  --paper: #e7e5e0;
  --surface: #f5f4f0;
  --well: #d6d3cc;
  --dot-off: #cbc7bf;
  --line: #c4c0b8;
  --ink: #111111;
  --ink-muted: #57534d;
  --ink-faint: #8f8a82;
  --klein: #002fa7;
  --on-klein: #ffffff;
  --klein-ink: #002fa7;
  --klein-soft: #cdd5ec;
  --sol: #ffd447;
  --on-sol: #111111;
  --rams: #f2581e;
  --on-rams: #111111;
  --tabaco: #a8532a;
  --on-tabaco: #ffffff;
  --salvia: #b7c0ae;
  --lavanda: #aeadbe;
  --malva: #c4b2b9;
  --verde: #1f5a3a;
  --on-verde: #ffffff;
  --rec: #d42a20;
  --on-rec: #ffffff;
  --focus: var(--klein-ink);
  --shadow-none: none;
  --shadow-press: inset 0 2px 0 rgba(0,0,0,0.10);
  --shadow-lift: 0 1px 1px rgba(0,0,0,0.06), 0 8px 18px -10px rgba(0,0,0,0.45);
  --shadow-float: 0 1px 2px rgba(0,0,0,0.10), 0 12px 28px -12px rgba(0,0,0,0.35);
}
[data-theme="dark"] {
  color-scheme: dark;
  --paper: #0e0e0d;
  --surface: #1b1a18;
  --well: #292724;
  --dot-off: #33302c;
  --line: #3a3732;
  --ink: #f2f0ea;
  --ink-muted: #a8a39a;
  --ink-faint: #6c6861;
  --klein: #2251e0;
  --on-klein: #ffffff;
  --klein-ink: #93a8ff;
  --klein-soft: #16244f;
  --sol: #ffd447;
  --on-sol: #111111;
  --rams: #ff6a2e;
  --on-rams: #111111;
  --tabaco: #c8703f;
  --on-tabaco: #111111;
  --salvia: #2b3128;
  --lavanda: #2c2b38;
  --malva: #382d31;
  --verde: #2f7d52;
  --on-verde: #ffffff;
  --rec: #ff4a3d;
  --on-rec: #111111;
  --focus: var(--klein-ink);
  --shadow-none: none;
  --shadow-press: inset 0 2px 0 rgba(0,0,0,0.45);
  --shadow-lift: 0 0 0 1px rgba(255,255,255,0.06);
  --shadow-float: 0 1px 2px rgba(0,0,0,0.5), 0 12px 28px -12px rgba(0,0,0,0.8);
}
:root {
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;
  --space-9: 96px;
  --radius-0: 0px;
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 40px;
  --radius-full: 9999px;
  --dot-size: 6px;
  --dot-pitch: 10px;
  --hit-min: 56px;
  --key-m: 88px;
  --key-l: 120px;
  --key-xl: 168px;
  --hairline: 1px;
  --dur-press: 90ms;
  --dur-fast: 150ms;
  --dur-base: 220ms;
  --dur-sheet: 500ms;
  --dur-grow: 640ms;
  --stagger: 50ms;
  --ease-ui: cubic-bezier(0.3, 0.75, 0.1, 1);
  --ease-arrive: cubic-bezier(0.25, 0.8, 0.25, 1);
  --ease-travel: cubic-bezier(0.45, 0, 0.1, 1);
  --ease-throw: cubic-bezier(0.25, 1, 0.5, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-settle: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-press: cubic-bezier(0.2, 0.8, 0.2, 1);
  --font-sans: "Archivo", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-dot: "Doto", "Archivo", monospace;
  --font-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
}

/* Frekvens — componentes. Vive en @layer components, así que tus utilidades de Tailwind ganan siempre. */
@layer components {

/* Frekvens — plano, grande, de puntos. */
.frk-body, body[data-frekvens] { margin: 0; font-family: var(--font-sans); background: var(--paper); color: var(--ink); -webkit-font-smoothing: antialiased; }
.frk-pad { padding: var(--space-5); }
.frk-row-flex { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: flex-end; }
.frk-cap { font-family: var(--font-mono); font-size: 11px; line-height: 14px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); margin: 0 0 var(--space-2); }

/* tones: background + its on-colour, shared by keys, tiles, strips, chips */
.frk-tone--paper   { background: var(--surface); --tone-bg: var(--surface); color: var(--ink); }
.frk-tone--surface { background: var(--surface); --tone-bg: var(--surface); color: var(--ink); }
.frk-tone--well    { background: var(--well); --tone-bg: var(--well); color: var(--ink); }
.frk-tone--ink     { background: var(--ink); --tone-bg: var(--ink); color: var(--paper); }
.frk-tone--klein   { background: var(--klein); --tone-bg: var(--klein); color: var(--on-klein); }
.frk-tone--klein-soft { background: var(--klein-soft); --tone-bg: var(--klein-soft); color: var(--ink); }
.frk-tone--sol     { background: var(--sol); --tone-bg: var(--sol); color: var(--on-sol); }
.frk-tone--rams    { background: var(--rams); --tone-bg: var(--rams); color: var(--on-rams); }
.frk-tone--tabaco  { background: var(--tabaco); --tone-bg: var(--tabaco); color: var(--on-tabaco); }
.frk-tone--rec     { background: var(--rec); --tone-bg: var(--rec); color: var(--on-rec); }
.frk-tone--salvia  { background: var(--salvia); --tone-bg: var(--salvia); color: var(--ink); }
/* on ambient grounds the muted ink darkens so second lines keep 4.5:1 */
html:not([data-theme="dark"]) :is(.frk-tone--salvia, .frk-tone--lavanda, .frk-tone--malva) { --ink-muted: #3d3934; }
.frk-tone--lavanda { background: var(--lavanda); --tone-bg: var(--lavanda); color: var(--ink); }
.frk-tone--malva   { background: var(--malva); --tone-bg: var(--malva); color: var(--ink); }

:where(.frk-key, .frk-keypad__key, .frk-seg__opt, .frk-switch, .frk-tile, .frk-row, .frk-dial__knob):focus-visible,
.frk-slider input:focus-visible + * { outline: 2px solid var(--focus); outline-offset: 2px; }

/* KeyButton */
.frk-key { position: relative; display: inline-flex; flex-direction: column; justify-content: space-between; align-items: flex-start;
  min-width: var(--key-m); min-height: var(--key-m); padding: var(--space-3) var(--space-4); border: 0; border-radius: var(--radius-lg);
  font: 700 20px/24px var(--font-sans); letter-spacing: -.01em; text-align: left; cursor: pointer; box-shadow: var(--shadow-none);
  transition: transform var(--dur-press, 90ms) var(--ease-ui, ease-out), box-shadow var(--dur-press, 90ms) var(--ease-ui, ease-out), background-color var(--dur-fast, 150ms) var(--ease-ui, ease-out), color var(--dur-fast, 150ms); -webkit-tap-highlight-color: transparent; }
.frk-key:active:not(:disabled) { box-shadow: var(--shadow-press); transform: scale(.965); }
.frk-key.is-active, .frk-key[data-open] { box-shadow: var(--shadow-press); }
.frk-key.frk-tone--paper.is-active { background: var(--ink); color: var(--paper); }
.frk-key:disabled { background: var(--well); color: var(--ink-faint); cursor: not-allowed; box-shadow: none; transform: none; }
.frk-key__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; opacity: .9; }
.frk-key__main { display: flex; align-items: center; gap: var(--space-2); margin-top: auto; }
.frk-key--s  { min-width: var(--hit-min); min-height: var(--hit-min); padding: var(--space-3); border-radius: var(--radius-md); font-size: 15px; }
.frk-key--l  { min-width: var(--key-l); min-height: var(--key-l); font-size: 28px; line-height: 30px; }
.frk-key--xl { min-width: var(--key-xl); min-height: var(--key-xl); border-radius: var(--radius-xl); padding: var(--space-5); font-size: 40px; line-height: 40px; font-weight: 800; letter-spacing: -.03em; }
.frk-key--block { width: 100%; }
.frk-key--pill { border-radius: var(--radius-full); min-height: var(--hit-min); flex-direction: row; align-items: center; justify-content: center; padding: 0 var(--space-6); font-size: 17px; }
.frk-key--pill .frk-key__main { margin: 0; }
.frk-key--round { border-radius: var(--radius-full); align-items: center; justify-content: center; padding: 0; }
.frk-key--round .frk-key__main { margin: 0; }
.frk-key--round .frk-key__label { position: absolute; top: auto; bottom: -22px; color: var(--ink-muted); }
.frk-key--round.frk-key--s, .frk-key--round.frk-key--m, .frk-key--round { width: var(--key-m); height: var(--key-m); }
.frk-key--round.frk-key--s { width: var(--hit-min); height: var(--hit-min); }
.frk-key--round.frk-key--l { width: var(--key-l); height: var(--key-l); }
.frk-key--round.frk-key--xl { width: var(--key-xl); height: var(--key-xl); }

/* Keypad */
.frk-keypad { display: grid; gap: var(--hairline); background: var(--line); border-radius: var(--radius-lg); overflow: hidden; height: var(--key-m); }
.frk-keypad__key { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-1); border: 0; border-radius: var(--radius-0);
  font: 500 15px/18px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; cursor: pointer; }
.frk-keypad__key:active { box-shadow: var(--shadow-press); }
.frk-keypad__key.frk-tone--paper.is-active { background: var(--ink); color: var(--paper); }
.frk-keypad__key .frk-icon:only-child { width: 28px; height: 28px; }

/* Dial */
.frk-dial { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-2); }
.frk-dial__knob { border-radius: var(--radius-full); cursor: grab; touch-action: none; }
.frk-dial__knob:active { cursor: grabbing; }
.frk-dial__disc { fill: var(--ink); }
.frk-dial--klein .frk-dial__disc { fill: var(--klein); }
.frk-dial--tabaco .frk-dial__disc { fill: var(--tabaco); }
.frk-dial__dot { fill: var(--paper); }
.frk-dial__needle { stroke: var(--sol); stroke-width: 1.2; stroke-linecap: round; }
.frk-dial__tick { fill: var(--dot-off); }
.frk-dial__tick.is-on { fill: var(--ink); }
.frk-dial__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }

/* Gauge */
.frk-gauge { display: inline-flex; flex-direction: column; align-items: center; }
.frk-gauge svg { display: block; overflow: visible; }
.frk-gauge__track { fill: none; stroke: var(--tabaco); stroke-linecap: round; }
.frk-gauge__fill { fill: none; stroke: var(--ink); stroke-linecap: round; }
.frk-gauge__dot { fill: var(--ink); stroke: var(--tabaco); stroke-width: 2; }
.frk-gauge__caption { margin-top: calc(var(--space-6) * -1); font: 500 15px/18px var(--font-sans); }

/* Slider */
.frk-slider { display: flex; flex-direction: column; gap: var(--space-2); }
.frk-slider__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink); }
.frk-slider__track { position: relative; height: var(--hit-min); border-radius: var(--radius-full); background: var(--well); }
.frk-slider__end { position: absolute; top: 50%; width: 6px; height: 6px; margin-top: -3px; border-radius: var(--radius-full); background: var(--ink); }
.frk-slider__end--a { left: 22px; } .frk-slider__end--b { right: 22px; }
.frk-slider__thumb { position: absolute; top: 50%; width: 24px; height: 24px; margin: -12px 0 0 -12px; border-radius: var(--radius-full); background: var(--rams); pointer-events: none; }
.frk-slider input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.frk-slider__track:focus-within { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-slider__stops { display: flex; justify-content: space-between; padding: 0 var(--space-3); font: 13px/18px var(--font-sans); color: var(--ink-muted); }

/* Switch: el disco viaja de un extremo a otro, se estira al pulsar y aterriza suave (ease-settle, sin rebote) */
.frk-switch { position: relative; flex: none; display: inline-block; width: 120px; height: var(--hit-min); padding: 0; border: 0; border-radius: var(--radius-full); overflow: hidden;
  background: var(--well); color: var(--ink); font: 700 13px/1 var(--font-mono); letter-spacing: .08em; cursor: pointer; -webkit-tap-highlight-color: transparent;
  box-shadow: inset 0 0 0 0 transparent, inset 0 1px 2px rgba(0,0,0,.06);
  transition: background-color var(--dur-base, 220ms) var(--ease-ui, ease-out), color var(--dur-base, 220ms), box-shadow var(--dur-fast, 150ms); }
.frk-switch:hover:not(:disabled) { box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--ink) 22%, transparent), inset 0 1px 2px rgba(0,0,0,.06); }
.frk-switch__dot { position: absolute; left: 8px; top: 8px; width: 40px; height: 40px; box-sizing: border-box; border-radius: var(--radius-full); border: 2.5px solid var(--ink); background: transparent;
  box-shadow: 0 1px 0 rgba(0,0,0,0), 0 0 0 0 transparent;
  transition: transform 250ms var(--ease-settle, cubic-bezier(.22,1,.36,1)), width var(--dur-fast, 150ms) var(--ease-ui, ease-out), background-color var(--dur-fast, 150ms), border-color var(--dur-fast, 150ms), box-shadow var(--dur-base, 220ms); }
.frk-switch:active:not(:disabled) .frk-switch__dot { width: 50px; }
.frk-switch.is-on { background: var(--ink); color: var(--paper); }
.frk-switch.is-on .frk-switch__dot { transform: translateX(64px); background: var(--sol); border-color: var(--sol); box-shadow: 0 0.5px 1.5px rgba(0,0,0,.24), 0 0 0 0.5px rgba(0,0,0,.08); }
.frk-switch.is-on:active:not(:disabled) .frk-switch__dot { transform: translateX(54px); }
.frk-switch__text { position: absolute; top: 50%; transition: opacity var(--dur-fast, 150ms) var(--ease-ui, ease-out), transform var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-switch__text--off { right: 20px; transform: translateY(-50%); }
.frk-switch__text--on { left: 20px; transform: translate(-8px, -50%); opacity: 0; }
.frk-switch.is-on .frk-switch__text--on { transform: translate(0, -50%); opacity: 1; }
.frk-switch.is-on .frk-switch__text--off { transform: translate(8px, -50%); opacity: 0; }
.frk-switch:disabled { color: var(--ink-faint); cursor: not-allowed; }
.frk-switch:disabled .frk-switch__dot { border-color: var(--ink-faint); }
.frk-switchrow { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); min-height: var(--hit-min); }
.frk-switchrow__label { font: 600 16px/22px var(--font-sans); cursor: pointer; }

/* Segmented: el fondo elegido es una pieza que viaja entre opciones */
.frk-seg { position: relative; isolation: isolate; display: inline-flex; padding: 4px; gap: 4px; border-radius: var(--radius-full); background: var(--ink); }
.frk-seg__opt { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: var(--space-2); min-height: 48px; min-width: 48px; justify-content: center; padding: 0 var(--space-5); border: 0; border-radius: var(--radius-full);
  background: transparent; color: var(--paper); font: 700 15px/18px var(--font-sans); cursor: pointer; -webkit-tap-highlight-color: transparent;
  transition: background-color var(--dur-fast, 150ms) var(--ease-travel, ease), color var(--dur-base, 220ms) var(--ease-ui, ease-out), transform var(--dur-press, 90ms) var(--ease-ui, ease-out); }
.frk-seg__opt.is-on { background: var(--paper); color: var(--ink); }
.frk-seg.has-thumb .frk-seg__opt.is-on { background: transparent; }
.frk-seg__opt:not(.is-on):hover { color: color-mix(in srgb, var(--paper) 100%, transparent); background: color-mix(in srgb, var(--paper) 10%, transparent); }
.frk-seg__opt:active { transform: scale(.965); }
.frk-seg__thumb { position: absolute; left: 0; top: 0; z-index: 0; border-radius: var(--radius-full); background: var(--paper); box-shadow: 0 0.5px 1.5px rgba(0,0,0,.14), 0 0 0 0.5px rgba(0,0,0,.04);
  transition: scale var(--dur-press, 90ms) var(--ease-press, cubic-bezier(.2,.8,.2,1)); will-change: transform; }
.frk-seg__thumb.is-still { transition: none; }
.frk-seg:has(.frk-seg__opt:active) .frk-seg__thumb { scale: .97; }
.frk-seg__opt:only-child, .frk-seg__opt:has(.frk-icon:only-child) { padding: 0 var(--space-3); }

/* DotMatrix */
.frk-dm { display: block; }
.frk-dm__on { fill: var(--ink); }
.frk-dm__off { fill: var(--dot-off); }
.frk-dm--klein .frk-dm__on { fill: var(--klein); }
.frk-dm--rams .frk-dm__on { fill: var(--rams); }
.frk-dm--tabaco .frk-dm__on { fill: var(--tabaco); }
.frk-dm--paper .frk-dm__on { fill: var(--paper); }

/* DotGrid */
.frk-dotgrid { display: grid; }
.frk-dotgrid__dot { border-radius: var(--radius-full); background: var(--surface); }
.frk-dotgrid--rams .is-on { background: var(--rams); }
.frk-dotgrid--ink .is-on { background: var(--ink); }
.frk-dotgrid--klein .is-on { background: var(--klein); }
.frk-dotgrid--sol .is-on { background: var(--sol); }

/* StateMark */
.frk-state { display: inline-flex; align-items: center; gap: var(--space-2); color: inherit; font: 500 15px/18px var(--font-sans); }
.frk-state svg { display: block; flex: none; }

/* LevelBars */
.frk-levels { display: flex; gap: 6px; align-items: stretch; }
.frk-levels__bar { flex: 1; min-width: 4px; max-width: 8px; border-radius: var(--radius-full); background: var(--ink-faint); }
.frk-levels__bar.is-on { background: var(--ink); }

/* BarMeter */
.frk-bars { display: flex; gap: var(--space-3); align-items: flex-end; }
.frk-bars__col { display: flex; flex-direction: column; align-items: center; gap: var(--space-2); }
.frk-bars__slot { display: flex; align-items: flex-end; }
.frk-bars__bar { width: 100%; border-radius: var(--radius-full); background: var(--well); }
.frk-bars__bar.is-on { background: var(--ink); }
.frk-bars__bar.is-hatched { background: repeating-linear-gradient(135deg, var(--ink-faint) 0 3px, transparent 3px 8px); }
.frk-bars__lbl { font: 500 13px/18px var(--font-sans); color: var(--ink-muted); }
.frk-bars__lbl.is-on { color: var(--ink); font-weight: 700; }

/* Readout */
.frk-readout { display: flex; flex-direction: column; gap: var(--space-1); }
.frk-readout__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-readout__value { font-family: var(--font-dot); font-weight: 800; color: var(--ink); font-variant-numeric: tabular-nums; }
.frk-readout--hero .frk-readout__value { font-size: 120px; line-height: .9; letter-spacing: -.02em; }
.frk-readout--display .frk-readout__value { font-size: 64px; line-height: 1; }
.frk-readout--label .frk-readout__value { font-size: 24px; line-height: 28px; font-weight: 700; }
.frk-readout__unit { font: 500 14px/18px var(--font-mono); margin-left: var(--space-2); color: var(--ink-muted); letter-spacing: .04em; }
.frk-readout__meta { font: 500 14px/18px var(--font-mono); color: var(--ink-muted); }

/* Tile */
.frk-tile { display: flex; flex-direction: column; gap: var(--space-3); min-height: 200px; padding: var(--space-4); border: 0; border-radius: var(--radius-lg); text-align: left; box-sizing: border-box; font-family: var(--font-sans); }
button.frk-tile { cursor: pointer; }
.frk-tile__head { display: flex; justify-content: space-between; align-items: flex-start; gap: var(--space-2); }
.frk-tile__title { font: 700 17px/20px var(--font-sans); letter-spacing: -.01em; display: flex; flex-direction: column; }
.frk-tile__sub { font-weight: 400; }
:where(.frk-tone--surface, .frk-tone--paper, .frk-tone--well) .frk-tile__sub { color: var(--ink-muted); }
.frk-tile__meta { font: 500 11px/14px var(--font-mono); letter-spacing: .06em; }
.frk-tile__art { flex: 1; display: flex; align-items: center; justify-content: center; }
.frk-tile__value { font: 400 64px/.9 var(--font-sans); letter-spacing: -.04em; }

/* Strip */
.frk-strip { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); min-height: 120px; padding: var(--space-3) var(--space-4); border-radius: var(--radius-md); box-sizing: border-box; overflow: hidden; }
.frk-strip__title { font: 500 17px/20px var(--font-sans); }
.frk-strip__value { font: 500 64px/1 var(--font-sans); letter-spacing: -.03em; white-space: nowrap; }
.frk-strip__inst { flex: 1; display: flex; justify-content: flex-end; align-items: center; min-width: 0; }

/* ListRow */
.frk-row { display: grid; grid-template-columns: 72px 1fr auto; align-items: start; gap: var(--space-4); width: 100%; padding: var(--space-4) 0; border: 0; border-top: var(--hairline) solid var(--line);
  background: transparent; color: inherit; text-align: left; font-family: var(--font-sans); }
button.frk-row { cursor: pointer; }
.frk-row__lead { font: 400 40px/1 var(--font-sans); letter-spacing: -.03em; }
.frk-row__body { display: flex; flex-direction: column; gap: var(--space-1); }
.frk-row__title { font: 400 20px/24px var(--font-sans); }
.frk-row__detail { font: 13px/18px var(--font-sans); color: var(--ink-muted); }
.frk-row__value { font: 500 14px/24px var(--font-mono); }

/* Chip */
.frk-chip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 var(--space-3); border-radius: var(--radius-full); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.frk-chip--sq { border-radius: var(--radius-sm); }
.frk-chip__dot { width: 8px; height: 8px; border-radius: var(--radius-full); background: currentColor; }
.frk-chip.frk-tone--well .frk-chip__dot { background: var(--rec); }



/* art inside a toned surface follows that surface's on-colour */
:where(.frk-tile, .frk-strip, .frk-key) .frk-dm--ink .frk-dm__on { fill: currentColor; }
:where(.frk-tile, .frk-strip) .frk-dotgrid--ink .is-on { background: currentColor; }
:where(.frk-tile, .frk-strip) .frk-dotgrid__dot:not(.is-on) { background: var(--well); }

/* ================= Frekvens 2: overlays, inputs, motion ================= */
.frk-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.frk-tone--verde { background: var(--verde); --tone-bg: var(--verde); color: var(--on-verde); }
/* inside a coloured block, secondary text uses the block's own on-colour */
.frk-tone--klein { --ink-muted: var(--on-klein); } .frk-tone--sol { --ink-muted: var(--on-sol); } .frk-tone--rams { --ink-muted: var(--on-rams); }
.frk-tone--tabaco { --ink-muted: var(--on-tabaco); } .frk-tone--verde { --ink-muted: var(--on-verde); } .frk-tone--rec { --ink-muted: var(--on-rec); } .frk-tone--ink { --ink-muted: var(--paper); }

/* field scaffolding shared by Select, TextField */
.frk-field, .frk-select { position: relative; display: inline-flex; flex-direction: column; gap: var(--space-2); min-width: 240px; }
.frk-select--block, .frk-field { width: 100%; }
.frk-field__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-field__hint { font: 13px/18px var(--font-sans); color: var(--ink-muted); }
.frk-field__error { display: inline-flex; align-items: center; gap: 6px; font: 500 13px/18px var(--font-sans); color: var(--ink); }
.frk-field__error .frk-icon { color: var(--rec); }
.frk-field__row { display: flex; gap: var(--space-2); align-items: center; margin: 0; }
.frk-input { flex: 1; min-width: 0; height: var(--hit-min); padding: 0 var(--space-5); border: 2px solid transparent; border-radius: var(--radius-full); background: var(--well); color: var(--ink);
  font: 400 17px/22px var(--font-sans); outline: none; transition: border-color var(--dur-fast, 150ms), background-color var(--dur-fast, 150ms); box-sizing: border-box; }
.frk-field > .frk-input { flex: none; width: 100%; }
.frk-input--mono { font-family: var(--font-mono); letter-spacing: .02em; }
.frk-input::placeholder { color: var(--ink-muted); }
.frk-input:hover { background: var(--dot-off); }
.frk-input:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; background: var(--surface); }
.frk-field.is-error .frk-input { border-color: var(--rec); }
.frk-field__go { width: var(--hit-min); height: var(--hit-min); min-width: 0; min-height: 0; flex: none; }

/* popover surface: pinned to the edge it opened from, never pops */
.frk-pop { position: absolute; z-index: 50; top: calc(100% + 8px); left: 0; margin: 0; padding: 6px; list-style: none; min-width: 100%; box-sizing: border-box;
  background: var(--ink); color: var(--paper); border-radius: var(--radius-lg); transform-origin: top left;
  opacity: 0; transform: translateY(-6px) scale(.96);
  transition: opacity var(--dur-fast, 150ms) var(--ease-exit, ease-in), transform var(--dur-fast, 150ms) var(--ease-exit, ease-in); }
.frk-pop.is-in { opacity: 1; transform: none; transition-duration: var(--dur-base, 220ms); transition-timing-function: var(--ease-ui, ease-out); }
.frk-pop > * { opacity: 0; transform: translateY(-4px); transition: opacity var(--dur-fast, 150ms) var(--ease-ui, ease-out), transform var(--dur-fast, 150ms) var(--ease-ui, ease-out); }
.frk-pop.is-in > * { opacity: 1; transform: none; }

/* Select */
.frk-select__trigger { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); height: var(--hit-min); padding: 0 var(--space-4) 0 var(--space-5);
  border: 2px solid transparent; border-radius: var(--radius-full); background: var(--well); color: var(--ink); font: 700 17px/22px var(--font-sans); text-align: left; cursor: pointer;
  transition: background-color var(--dur-fast, 150ms), transform var(--dur-press, 90ms) var(--ease-ui, ease-out); }
.frk-select__trigger:hover { background: var(--dot-off); }
.frk-select__trigger:active { transform: scale(.985); }
.frk-select__trigger[data-open] { background: var(--ink); color: var(--paper); }
.frk-select__trigger:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-select__trigger:disabled { color: var(--ink-faint); cursor: not-allowed; }
.frk-select__value.is-placeholder { color: var(--ink-muted); font-weight: 400; }
.frk-select__chev { transition: transform var(--dur-base, 220ms) var(--ease-ui, ease-out); flex: none; }
.frk-select__trigger[data-open] .frk-select__chev { transform: rotate(180deg); }
.frk-select .frk-pop { top: calc(100% + 8px); }
.frk-field__label + .frk-select__trigger + .frk-pop { top: calc(100% + 8px); }
.frk-select__opt { display: flex; align-items: center; gap: var(--space-3); min-height: 48px; padding: 0 var(--space-4); border-radius: var(--radius-md); cursor: pointer; font: 500 16px/20px var(--font-sans); }
.frk-select__opt > span:first-child { flex: 1; }
.frk-select__opt.is-active { background: color-mix(in srgb, var(--paper) 14%, transparent); }
.frk-select__opt.is-selected { font-weight: 700; }
.frk-select__opt[aria-disabled] { opacity: .45; cursor: not-allowed; }
.frk-select__meta { font: 500 11px/14px var(--font-mono); letter-spacing: .06em; opacity: .7; }
.frk-select__opt .frk-icon { color: var(--sol); }
.frk-select__trigger[data-open] .frk-select__value.is-placeholder { color: inherit; }

/* Menu */
.frk-menu { position: relative; display: inline-block; }
.frk-menu__trigger { position: relative; }
.frk-menu__list { width: max-content; min-width: 220px; }
.frk-menu--end .frk-menu__list { left: auto; right: 0; transform-origin: top right; }
.frk-menu__item { display: flex; align-items: center; gap: var(--space-3); width: 100%; min-height: 48px; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-md);
  background: transparent; color: inherit; font: 500 16px/20px var(--font-sans); text-align: left; cursor: pointer; }
.frk-menu__item > span:nth-child(2) { flex: 1; }
.frk-menu__item:hover, .frk-menu__item:focus-visible { background: color-mix(in srgb, var(--paper) 14%, transparent); outline: none; }
.frk-menu__item:focus-visible { box-shadow: inset 0 0 0 2px var(--sol); }
.frk-menu__item.is-danger .frk-icon { color: var(--rams); }
.frk-menu__item.is-danger { font-weight: 700; }
.frk-menu__item[aria-disabled] { opacity: .45; cursor: not-allowed; }
.frk-menu__noicon { width: 20px; }
.frk-menu__kbd { font: 500 11px/14px var(--font-mono); letter-spacing: .06em; opacity: .7; }
.frk-menu__sep { height: 1px; margin: 6px var(--space-3); background: color-mix(in srgb, var(--paper) 18%, transparent); }

/* Sheet */
.frk-sheet { position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column; justify-content: flex-end; }
.frk-sheet--inline { position: absolute; }
.frk-sheet__scrim { position: absolute; inset: 0; background: rgba(0,0,0,.4); opacity: 0; transition: opacity var(--dur-base, 220ms) var(--ease-exit, ease-in); }
.frk-sheet.is-in .frk-sheet__scrim { opacity: 1; transition-timing-function: var(--ease-ui, ease-out); }
.frk-sheet__panel { position: relative; max-height: 88%; overflow: auto; padding: 0 var(--space-5) var(--space-6); border-radius: var(--radius-xl) var(--radius-xl) 0 0; outline: none;
  transform: translateY(100%); transition: transform var(--dur-base, 220ms) var(--ease-exit, ease-in); }
.frk-sheet.is-in .frk-sheet__panel { transform: none; transition: transform var(--dur-sheet, 500ms) var(--ease-ui, ease-out); }
.frk-sheet.is-in .frk-sheet__panel.is-dragging { transition: none; }
.frk-sheet__grab { display: flex; justify-content: center; padding: var(--space-3) 0 var(--space-2); cursor: grab; touch-action: none; }
.frk-sheet__grab span { width: 40px; height: 5px; border-radius: var(--radius-full); background: var(--dot-off); }
.frk-sheet__head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-4); padding: var(--space-2) 0 var(--space-5); }
.frk-sheet__title { margin: 0; font: 800 32px/1 var(--font-sans); letter-spacing: -.02em; }
.frk-sheet__body { display: flex; flex-direction: column; gap: var(--space-4); }

/* Toast */
.frk-toast { display: inline-flex; align-items: center; gap: var(--space-3); min-height: var(--hit-min); padding: 0 var(--space-2) 0 var(--space-5); border-radius: var(--radius-full); max-width: 100%; box-sizing: border-box;
  font: 500 15px/20px var(--font-sans); opacity: 0; transform: translateY(12px) scale(.98); transition: opacity var(--dur-fast, 150ms) var(--ease-exit, ease-in), transform var(--dur-fast, 150ms) var(--ease-exit, ease-in); }
.frk-toast.is-in { opacity: 1; transform: none; transition-duration: var(--dur-base, 220ms); transition-timing-function: var(--ease-ui, ease-out); }
.frk-toast--fixed { position: fixed; left: 50%; bottom: var(--space-8); translate: -50% 0; z-index: 120; }
.frk-toast__text { flex: 1; padding: var(--space-3) 0; }
.frk-toast__action { height: 40px; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-full); background: var(--sol); color: var(--on-sol); font: 700 14px/18px var(--font-sans); cursor: pointer; }
.frk-toast__close { width: 40px; height: 40px; border: 0; border-radius: var(--radius-full); background: transparent; color: inherit; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; }
.frk-toast__action:focus-visible, .frk-toast__close:focus-visible { outline: 2px solid var(--sol); outline-offset: 2px; }

/* Stepper: digits roll in */
.frk-stepper { display: inline-flex; align-items: center; gap: var(--space-4); }
.frk-stepper__val { display: flex; align-items: baseline; gap: var(--space-1); min-width: 2.2em; justify-content: center; overflow: hidden; }
.frk-stepper__num { display: inline-block; font: 400 64px/1 var(--font-sans); letter-spacing: -.04em; font-variant-numeric: tabular-nums; animation: frk-roll var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-stepper__unit { font: 500 14px/18px var(--font-mono); color: var(--ink-muted); }
@keyframes frk-roll { from { transform: translateY(40%); opacity: 0; } to { transform: none; opacity: 1; } }

/* ProgressRing */
.frk-ring { position: relative; display: inline-flex; align-items: center; justify-content: center; }
.frk-ring svg { position: absolute; inset: 0; }
.frk-ring__track { fill: none; stroke: var(--well); }
.frk-ring__fill { fill: none; stroke: var(--rams); stroke-linecap: round; transition: stroke-dashoffset var(--dur-grow, 640ms) var(--ease-arrive, ease-out); }
.frk-ring--klein .frk-ring__fill { stroke: var(--klein); } .frk-ring--ink .frk-ring__fill { stroke: var(--ink); } .frk-ring--verde .frk-ring__fill { stroke: var(--verde); }
.frk-ring__text { position: relative; font: 500 20px/1 var(--font-sans); font-variant-numeric: tabular-nums; }

/* SlideToStart */
.frk-slide { position: relative; display: flex; align-items: center; height: 72px; padding: 4px; border-radius: var(--radius-full); box-sizing: border-box; overflow: hidden; user-select: none; }
.frk-slide__text { position: absolute; left: 0; right: 0; text-align: center; padding-left: 64px; font: 700 18px/22px var(--font-sans); pointer-events: none; transition: opacity var(--dur-fast, 150ms); }
.frk-slide__knob { position: relative; z-index: 1; width: 64px; height: 64px; border: 0; border-radius: var(--radius-full); background: var(--ink); color: var(--paper); cursor: grab; touch-action: none;
  display: inline-flex; align-items: center; justify-content: center; transition: transform var(--dur-sheet, 500ms) var(--ease-throw, ease-out), background-color var(--dur-fast, 150ms); }
.frk-slide__knob.is-dragging { transition: none; cursor: grabbing; }
.frk-slide__knob:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-slide.is-done .frk-slide__knob { background: var(--verde); color: var(--on-verde); }

/* CardStack: overlap, the open card grows with a long brake */
.frk-stack { display: flex; flex-direction: column; }
.frk-stack__item { position: relative; }
.frk-stack__item + .frk-stack__item { margin-top: calc(var(--radius-lg) * -1); }
.frk-stack__card { display: flex; flex-direction: column; justify-content: space-between; width: 100%; height: 112px; padding: var(--space-4) var(--space-4) calc(var(--radius-lg) + var(--space-3)); border: 0;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0; text-align: left; cursor: pointer; box-sizing: border-box; font-family: var(--font-sans);
  transition: height var(--dur-grow, 640ms) var(--ease-arrive, ease-out); }
.frk-stack__item:last-child .frk-stack__card { border-radius: var(--radius-lg); padding-bottom: var(--space-4); }
.frk-stack__card.is-open { height: 216px; }
.frk-stack__card:focus-visible { outline: 2px solid var(--focus); outline-offset: -4px; }
.frk-stack__top { display: flex; justify-content: space-between; }
.frk-stack__badge { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: var(--radius-full); border: 1.5px dashed currentColor; font: 800 20px/1 var(--font-sans); }
.frk-stack__bottom { display: flex; justify-content: space-between; align-items: flex-end; gap: var(--space-3); }
.frk-stack__title { display: flex; flex-direction: column; font: 800 24px/1.05 var(--font-sans); letter-spacing: -.02em; }
.frk-stack__sub { font: 400 14px/18px var(--font-sans); margin-top: var(--space-1); }
.frk-stack__value { font: 400 56px/.9 var(--font-sans); letter-spacing: -.04em; }
.frk-stack__card:not(.is-open) .frk-stack__bottom { opacity: 0; transform: translateY(8px); transition: opacity var(--dur-fast, 150ms), transform var(--dur-fast, 150ms); }
.frk-stack__card.is-open .frk-stack__bottom { opacity: 1; transform: none; transition: opacity var(--dur-base, 220ms) var(--ease-ui, ease-out) 200ms, transform var(--dur-base, 220ms) var(--ease-ui, ease-out) 200ms; }

/* LED */
.frk-led { display: inline-flex; align-items: center; gap: var(--space-2); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.frk-led__lamp { width: 10px; height: 6px; border-radius: 2px; background: var(--dot-off); transition: background-color var(--dur-fast, 150ms), box-shadow var(--dur-fast, 150ms); }
.frk-led--rec.is-on .frk-led__lamp { background: var(--rec); box-shadow: 0 0 0 3px color-mix(in srgb, var(--rec) 22%, transparent); }
.frk-led--verde.is-on .frk-led__lamp { background: var(--verde); box-shadow: 0 0 0 3px color-mix(in srgb, var(--verde) 22%, transparent); }
.frk-led--sol.is-on .frk-led__lamp { background: var(--sol); box-shadow: 0 0 0 3px color-mix(in srgb, var(--sol) 30%, transparent); }
.frk-led--klein.is-on .frk-led__lamp { background: var(--klein); box-shadow: 0 0 0 3px color-mix(in srgb, var(--klein) 22%, transparent); }
.frk-led.is-blink.is-on .frk-led__lamp { animation: frk-blink 1.2s steps(2, jump-none) infinite; }
@keyframes frk-blink { 50% { opacity: .25; } }

/* Grille */
.frk-grille { display: block; }
.frk-grille__body { fill: var(--verde); }
.frk-grille__hole { fill: var(--ink); }
.frk-grille--ink .frk-grille__body { fill: var(--ink); } .frk-grille--ink .frk-grille__hole { fill: var(--paper); }
.frk-grille--sol .frk-grille__body { fill: var(--sol); }
.frk-grille--rams .frk-grille__body { fill: var(--rams); }
.frk-grille--surface .frk-grille__body { fill: var(--surface); }
.frk-grille--tabaco .frk-grille__body { fill: var(--tabaco); }

.frk-dm circle { transition: r var(--dur-fast, 150ms) var(--ease-ui, ease-out); }

/* reduced motion: keep feedback, drop travel */
@media (prefers-reduced-motion: reduce) {
  .frk-pop, .frk-pop > *, .frk-sheet__panel, .frk-toast, .frk-stack__card, .frk-stack__bottom, .frk-ring__fill, .frk-slide__knob, .frk-select__chev, .frk-switch__dot { transition-duration: 1ms !important; animation: none !important; }
  .frk-key:active:not(:disabled) { transform: none; }
}

/* ================= Frekvens 3: tiempo, mecanismos, conversación ================= */
/* Stopwatch / Timer */
.frk-watch, .frk-timer { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-5); }
.frk-watch { align-items: stretch; min-width: 280px; }
.frk-watch__keys { display: flex; justify-content: space-between; gap: var(--space-4); }
.frk-timer .frk-watch__keys { width: 100%; }
.frk-watch__laps { list-style: none; margin: 0; padding: 0; max-height: 180px; overflow: auto; }
.frk-watch__lap { display: grid; grid-template-columns: 56px 1fr auto; gap: var(--space-3); padding: var(--space-3) 0; border-top: var(--hairline) solid var(--line); font: 500 14px/18px var(--font-mono); font-variant-numeric: tabular-nums; animation: frk-in var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-watch__lap span:first-child { color: var(--ink-muted); }
.frk-watch__lap.is-best span:nth-child(2) { color: var(--klein-ink); font-weight: 700; }
@keyframes frk-in { from { opacity: 0; transform: translateY(-6px); } }
.frk-timer__face { position: relative; }
.frk-timer__face svg { position: absolute; inset: 0; }
.frk-timer__face circle { fill: var(--dot-off); transition: fill var(--dur-fast, 150ms); }
.frk-timer__face circle.is-on { fill: var(--rams); }
.frk-timer.is-done .frk-timer__face circle { fill: var(--verde); }
.frk-timer__center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-1); }
.frk-timer__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-timer__value { font: 800 56px/1 var(--font-dot); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
.frk-timer__value.is-count { font-size: 120px; animation: frk-pop-num 1s var(--ease-arrive, ease-out); }
@keyframes frk-pop-num { 0% { transform: scale(1.25); opacity: 0; } 25% { transform: scale(1); opacity: 1; } 100% { opacity: .85; } }

/* Hourglass */
.frk-hourglass { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-3); }
.frk-hourglass__body { border: 0; padding: var(--space-3); background: none; border-radius: var(--radius-lg); cursor: pointer; transition: transform var(--dur-grow, 640ms) var(--ease-arrive, ease-out); }
.frk-hourglass__body:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-hourglass circle { fill: var(--dot-off); transition: fill var(--dur-base, 220ms); }
.frk-hourglass circle.is-on { fill: var(--tabaco); }
.frk-hourglass__grain { animation: frk-grain 420ms linear infinite; }
@keyframes frk-grain { from { transform: translateY(-8px); opacity: 0; } 50% { opacity: 1; } to { transform: translateY(8px); opacity: 0; } }
.frk-hourglass__read { font: 500 14px/18px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink-muted); }

/* Pendulum */
.frk-pendulum { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-5); }
.frk-pendulum__stage { position: relative; width: 220px; height: 180px; }
.frk-pendulum__pivot { position: absolute; left: 50%; top: 0; width: 16px; height: 16px; margin-left: -8px; border-radius: var(--radius-full); background: var(--ink); }
.frk-pendulum__arm { position: absolute; left: 50%; top: 8px; width: 3px; height: 150px; margin-left: -1.5px; background: var(--ink); transform-origin: 50% 0; transform: rotate(0deg); }
.frk-pendulum__arm.is-run { animation: frk-swing 1s cubic-bezier(.37, 0, .63, 1) infinite; }
@keyframes frk-swing { 0% { transform: rotate(-28deg); } 50% { transform: rotate(28deg); } 100% { transform: rotate(-28deg); } }
.frk-pendulum__bob { position: absolute; left: 50%; bottom: -22px; width: 44px; height: 44px; margin-left: -22px; border-radius: var(--radius-full); background: var(--rams); }
.frk-pendulum__beats { display: flex; gap: var(--space-3); }
.frk-pendulum__beats span { width: 16px; height: 16px; border-radius: var(--radius-full); background: var(--dot-off); transition: background-color 60ms; }
.frk-pendulum__beats span.is-first { box-shadow: inset 0 0 0 2px var(--ink); }
.frk-pendulum__beats span.is-on { background: var(--ink); }
.frk-pendulum__ctrl { display: flex; align-items: center; gap: var(--space-5); }
.frk-pendulum .frk-stepper__num { font-size: 48px; }

/* Cabinet */
.frk-cabinet { display: flex; flex-direction: column; gap: var(--space-2); }
.frk-drawer { border-radius: var(--radius-md); overflow: hidden; transition: transform var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-drawer.is-open { transform: translateX(10px); }
.frk-drawer__front { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; width: 100%; min-height: 72px; padding: 0 var(--space-4); border: 0; background: transparent; color: inherit; cursor: pointer; text-align: left; font-family: var(--font-sans); }
.frk-drawer__front:focus-visible { outline: 2px solid var(--focus); outline-offset: -4px; border-radius: var(--radius-md); }
.frk-drawer__label { display: flex; align-items: baseline; gap: var(--space-3); font: 700 18px/22px var(--font-sans); }
.frk-drawer__index { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; }
.frk-drawer__handle { width: 56px; height: 10px; border-radius: var(--radius-full); background: currentColor; opacity: .85; transition: width var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-drawer.is-open .frk-drawer__handle { width: 72px; }
.frk-drawer__meta { justify-self: end; font: 500 11px/14px var(--font-mono); letter-spacing: .06em; }
.frk-drawer__body { display: grid; grid-template-rows: 0fr; visibility: hidden; transition: grid-template-rows var(--dur-base, 220ms) var(--ease-exit, ease-in), visibility 0s linear var(--dur-base, 220ms); }
.frk-drawer.is-open .frk-drawer__body { grid-template-rows: 1fr; visibility: visible; transition: grid-template-rows var(--dur-grow, 640ms) var(--ease-arrive, ease-out), visibility 0s; }
.frk-drawer__inner { overflow: hidden; }
.frk-drawer__pad { padding: 0 var(--space-4) var(--space-4); border-top: var(--hairline) dashed currentColor; padding-top: var(--space-4); font: 15px/21px var(--font-sans); }

/* Tabs */
.frk-tabs { display: flex; flex-direction: column; gap: var(--space-4); }
.frk-tabs__list { position: relative; display: inline-flex; align-self: flex-start; max-width: 100%; overflow-x: auto; scrollbar-width: none; }
.frk-tabs--pill .frk-tabs__list { padding: 4px; gap: 4px; border-radius: var(--radius-full); background: var(--well); }
.frk-tabs__tab { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: var(--space-2); min-height: 48px; padding: 0 var(--space-5); border: 0; border-radius: var(--radius-full); background: transparent; color: var(--ink-muted);
  font: 700 15px/18px var(--font-sans); white-space: nowrap; cursor: pointer; transition: color var(--dur-fast, 150ms); }
.frk-tabs__tab.is-on { color: var(--paper); }
.frk-tabs__tab:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-tabs__ind { position: absolute; z-index: 0; top: 4px; bottom: 4px; left: 0; border-radius: var(--radius-full); background: var(--ink); will-change: transform; } /* lo mueve useFollow: muelle con impulso */
.frk-tabs__count { min-width: 22px; height: 22px; padding: 0 6px; box-sizing: border-box; border-radius: var(--radius-full); background: var(--dot-off); color: var(--ink); font: 500 11px/22px var(--font-mono); text-align: center; }
.frk-tabs__tab.is-on .frk-tabs__count { background: var(--sol); color: var(--on-sol); }
/* folder variant: archive tabs */
.frk-tabs--folder { gap: 0; }
.frk-tabs--folder .frk-tabs__list { gap: 4px; align-items: flex-end; }
.frk-tabs--folder .frk-tabs__tab { min-height: 44px; border-radius: var(--radius-md) var(--radius-md) 0 0; padding: 0 var(--space-4); color: inherit; transform: translateY(6px); transition: transform var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-tabs--folder .frk-tabs__tab:not([class*="frk-tone--"]) { background: var(--well); }
.frk-tabs--folder .frk-tabs__tab.is-on { transform: none; }
.frk-tabs--folder .frk-tabs__tab:not(.is-on) { filter: saturate(.85); }
.frk-tabs--folder .frk-tabs__panel { border-radius: 0 var(--radius-lg) var(--radius-lg) var(--radius-lg); padding: var(--space-5); }
.frk-tabs--folder .frk-tabs__panel:not([class*="frk-tone--"]) { background: var(--surface); }
.frk-tabs__panel { outline: none; animation: frk-panel var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-tabs__panel:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
@keyframes frk-panel { from { opacity: 0; transform: translateY(8px); } }

/* Pager */
.frk-pager { display: flex; flex-direction: column; gap: var(--space-3); }
.frk-pager__track { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; overscroll-behavior-x: contain; border-radius: var(--radius-lg); }
.frk-pager__track::-webkit-scrollbar { display: none; }
.frk-pager__track:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-pager__slide { flex-shrink: 0; scroll-snap-align: start; }
.frk-pager__bar { display: flex; align-items: center; justify-content: space-between; }
.frk-pager__dots { display: flex; gap: 6px; }
.frk-pager__dots span { width: 8px; height: 8px; border-radius: var(--radius-full); background: var(--dot-off); transition: width var(--dur-base, 220ms) var(--ease-travel, ease), background-color var(--dur-fast, 150ms); }
.frk-pager__dots span.is-on { width: 24px; background: var(--ink); }
.frk-pager__btns { display: flex; gap: var(--space-2); }

/* Wheel */
.frk-wheel { position: relative; display: inline-block; width: 128px; }
.frk-wheel__window { position: absolute; left: 0; right: 0; border-radius: var(--radius-md); background: var(--surface); box-shadow: inset 0 0 0 var(--hairline) var(--line); }
.frk-wheel__scroll { position: relative; height: 100%; overflow-y: auto; scroll-snap-type: y mandatory; scrollbar-width: none; -webkit-mask-image: linear-gradient(transparent, #000 30%, #000 70%, transparent); mask-image: linear-gradient(transparent, #000 30%, #000 70%, transparent); }
.frk-wheel__scroll::-webkit-scrollbar { display: none; }
.frk-wheel__scroll:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-radius: var(--radius-md); }
.frk-wheel__item { display: flex; align-items: center; justify-content: center; scroll-snap-align: start; font: 500 32px/1 var(--font-sans); letter-spacing: -.02em; font-variant-numeric: tabular-nums; cursor: pointer; }
.frk-wheel__item.is-on { font-weight: 700; }
.frk-wheel:has(.frk-wheel__unit) .frk-wheel__item { padding-right: 28px; }
.frk-wheel__unit { position: absolute; right: 8px; height: 48px; display: flex; align-items: center; font: 500 11px/14px var(--font-mono); color: var(--ink-muted); pointer-events: none; }

/* VolumeWheel */
.frk-volume { display: inline-flex; align-items: stretch; gap: var(--space-4); }
.frk-volume__level { display: flex; flex-direction: column; justify-content: space-between; padding: 4px 0; }
.frk-volume__level span { width: 28px; flex: 1; max-height: 8px; margin: 3px 0; border-radius: var(--radius-full); background: var(--dot-off); transition: background-color 80ms; }
.frk-volume--rams .frk-volume__level span.is-on { background: var(--rams); }
.frk-volume--klein .frk-volume__level span.is-on { background: var(--klein); }
.frk-volume--ink .frk-volume__level span.is-on { background: var(--ink); }
.frk-volume__wheel { position: relative; width: 44px; border-radius: var(--radius-full); background: var(--ink); overflow: hidden; cursor: ns-resize; touch-action: none; box-shadow: inset 6px 0 8px rgba(0,0,0,.35), inset -6px 0 8px rgba(0,0,0,.35); }
.frk-volume__wheel:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-volume__ridges { position: absolute; left: 8px; right: 8px; top: -24px; bottom: -24px; background: repeating-linear-gradient(to bottom, var(--ink-muted) 0 2px, transparent 2px 12px); transition: transform 80ms linear; }
.frk-volume__read { display: flex; flex-direction: column; justify-content: flex-end; }
.frk-volume__num { font: 800 56px/1 var(--font-dot); font-variant-numeric: tabular-nums; }
.frk-volume__unit { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; color: var(--ink-muted); }

/* HoldButton */
.frk-hold { position: relative; display: inline-flex; align-items: center; justify-content: center; padding: 0; border: 0; border-radius: var(--radius-full); cursor: pointer; touch-action: none; user-select: none; -webkit-user-select: none; transition: transform var(--dur-press, 90ms) var(--ease-ui, ease-out); }
.frk-hold > svg { position: absolute; inset: 0; }
.frk-hold__track { fill: none; stroke: currentColor; opacity: .18; }
.frk-hold__fill { fill: none; stroke: var(--rams); stroke-linecap: round; }
.frk-hold.is-holding { transform: scale(.965); }
.frk-hold.is-done .frk-hold__fill { stroke: var(--verde); }
.frk-hold__main { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.frk-hold__text { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.frk-hold:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }

/* Rocker */
.frk-rockers { display: inline-flex; gap: var(--space-2); padding: var(--space-3); border-radius: var(--radius-lg); background: var(--verde); }
.frk-rocker { display: flex; flex-direction: column; align-items: center; gap: var(--space-2); color: var(--on-verde); }
.frk-rocker .frk-led__text { color: var(--on-verde); }
.frk-rocker__key { width: 64px; height: 80px; padding: 0; border: 0; border-radius: var(--radius-sm); background: #111111; perspective: 200px; cursor: pointer; }
.frk-rocker__face { display: flex; align-items: center; justify-content: center; width: 100%; height: 100%; border-radius: var(--radius-sm); background: #1e1e1e; color: #f2f0ea;
  box-shadow: inset 0 -10px 0 rgba(0,0,0,.35); transform: rotateX(14deg); transition: transform var(--dur-press, 90ms) var(--ease-ui, ease-out), box-shadow var(--dur-press, 90ms); }
.frk-rocker__key.is-on .frk-rocker__face { transform: rotateX(-14deg); box-shadow: inset 0 10px 0 rgba(0,0,0,.35); }
.frk-rocker__key:focus-visible { outline: 2px solid var(--sol); outline-offset: 3px; }

/* Reveal */
.frk-reveal__item { transition: opacity var(--dur-sheet, 500ms) var(--ease-arrive, ease-out), transform var(--dur-sheet, 500ms) var(--ease-arrive, ease-out), clip-path var(--dur-grow, 640ms) var(--ease-arrive, ease-out), filter var(--dur-sheet, 500ms); }
.frk-reveal--rise:not(.is-in) .frk-reveal__item { opacity: 0; transform: translateY(16px); }
.frk-reveal--scale:not(.is-in) .frk-reveal__item { opacity: 0; transform: scale(.94); }
.frk-reveal--wipe .frk-reveal__item { clip-path: inset(0 0 0 0 round var(--radius-lg)); }
.frk-reveal--wipe:not(.is-in) .frk-reveal__item { clip-path: inset(0 100% 0 0 round var(--radius-lg)); }
.frk-reveal--focus:not(.is-in) .frk-reveal__item { opacity: 0; filter: blur(6px); }
/* page transitions with the View Transitions API */
@view-transition { navigation: auto; }
::view-transition-old(root) { animation: 120ms var(--ease-exit, ease-in) both frk-vt-out; }
::view-transition-new(root) { animation: 200ms var(--ease-ui, ease-out) both frk-vt-in; }
@keyframes frk-vt-out { to { opacity: 0; } }
@keyframes frk-vt-in { from { opacity: 0; transform: translateY(8px); } }

/* Text primitives (generative composition) */
.frk-text { margin: 0; }
.frk-text--display-xl { font: 800 56px/.95 var(--font-sans); letter-spacing: -.03em; }
.frk-text--numeral-xl { font: 400 96px/.9 var(--font-sans); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
.frk-text--title { font: 800 32px/1 var(--font-sans); letter-spacing: -.02em; }
.frk-text--headline { font: 700 20px/24px var(--font-sans); letter-spacing: -.01em; }
.frk-text--body { font: 400 16px/22px var(--font-sans); }
.frk-text--body-strong { font: 700 16px/22px var(--font-sans); }
.frk-text--caption { font: 500 13px/18px var(--font-sans); }
.frk-text--label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }
.frk-text--readout { font: 500 14px/18px var(--font-mono); }
.frk-text--dot-hero { font: 800 120px/.9 var(--font-dot); letter-spacing: -.02em; }
.frk-text--dot-display { font: 800 64px/1 var(--font-dot); }
.frk-text.is-muted, .frk-text__sub { color: var(--ink-muted); }
.frk-text__sub { display: block; }
.frk-unknown { padding: var(--space-3) var(--space-4); border: 1.5px dashed var(--ink-muted); border-radius: var(--radius-md); font: 500 12px/16px var(--font-mono); color: var(--ink-muted); }

/* DotLoader */
.frk-loader { display: inline-flex; align-items: center; gap: 5px; }
.frk-loader > span:not(.frk-sr) { width: 7px; height: 7px; border-radius: var(--radius-full); background: currentColor; animation: frk-dot 1.1s var(--ease-ui, ease-out) infinite; }
.frk-loader--grid { display: inline-grid; grid-template-columns: repeat(3, 7px); gap: 4px; }
@keyframes frk-dot { 0%, 60%, 100% { opacity: .25; transform: scale(.8); } 30% { opacity: 1; transform: scale(1); } }

/* VoiceOrb */
.frk-orb { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-3); }
.frk-orb svg { display: block; }
.frk-orb circle { fill: var(--ink); }
.frk-orb--klein circle { fill: var(--klein); } .frk-orb--rams circle { fill: var(--rams); } .frk-orb--paper circle { fill: var(--paper); }
.frk-orb--idle circle { fill: var(--dot-off); }
.frk-orb__caption { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: inherit; }

/* Message */
.frk-msg { display: flex; gap: var(--space-3); max-width: 100%; animation: frk-in var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-msg--user { justify-content: flex-end; }
.frk-msg__avatar { flex: none; width: 28px; height: 28px; display: inline-flex; align-items: center; justify-content: center; border-radius: var(--radius-full); background: var(--ink); color: var(--paper); margin-top: 2px; }
.frk-msg__body { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; max-width: 100%; }
.frk-msg--user .frk-msg__body { align-items: flex-end; max-width: 82%; }
.frk-msg__name { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-msg__text { font: 400 17px/25px var(--font-sans); white-space: pre-wrap; overflow-wrap: anywhere; }
.frk-msg--user .frk-msg__text { padding: var(--space-3) var(--space-4); border-radius: var(--radius-lg) var(--radius-lg) var(--radius-sm) var(--radius-lg); background: var(--ink); color: var(--paper); }
.frk-msg--system .frk-msg__text { font: 500 12px/16px var(--font-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--ink-muted); }
.frk-msg--system { justify-content: center; }
.frk-msg__caret { display: inline-block; width: 9px; height: 9px; margin-left: 4px; border-radius: var(--radius-full); background: var(--rams); vertical-align: middle; animation: frk-blink 1s steps(2, jump-none) infinite; }
.frk-msg__ui { margin-top: var(--space-1); }
.frk-msg__meta { display: flex; align-items: center; gap: var(--space-1); font: 500 11px/14px var(--font-mono); color: var(--ink-muted); }
.frk-msg__act { width: 44px; height: 44px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: var(--radius-full); background: transparent; color: var(--ink-muted); cursor: pointer; }
.frk-msg__act:hover { background: var(--well); color: var(--ink); }
.frk-msg__act:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }

/* Suggestions */
.frk-suggest { display: flex; gap: var(--space-2); overflow-x: auto; scrollbar-width: none; padding: 2px; }
.frk-suggest__chip { flex: none; display: inline-flex; align-items: center; gap: 6px; height: 40px; padding: 0 var(--space-4); border: 1.5px solid currentColor; border-radius: var(--radius-full); background: transparent; color: inherit;
  font: 500 14px/18px var(--font-sans); cursor: pointer; animation: frk-in var(--dur-base, 220ms) var(--ease-ui, ease-out) both; transition: background-color var(--dur-fast, 150ms), color var(--dur-fast, 150ms), transform var(--dur-press, 90ms); }
.frk-suggest__chip:hover { background: color-mix(in srgb, currentColor 14%, transparent); }
.frk-suggest__chip:active { transform: scale(.965); }
.frk-suggest__chip:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }

/* Composer */
.frk-composer { display: flex; flex-direction: column; gap: var(--space-2); }
.frk-composer__bar { display: flex; align-items: flex-end; gap: var(--space-2); padding: 6px 6px 6px var(--space-5); border-radius: 30px; background: var(--well); transition: background-color var(--dur-fast, 150ms), box-shadow var(--dur-fast, 150ms); }
.frk-composer__bar:focus-within { background: var(--surface); box-shadow: inset 0 0 0 2px var(--focus); }
.frk-composer__input { flex: 1; align-self: stretch; min-height: var(--hit-min, 56px); max-height: 160px; padding: 17px 0; display: block; border: 0; outline: none; resize: none; background: transparent; color: var(--ink); font: 400 17px/22px var(--font-sans); box-sizing: border-box; }
.frk-composer__input::placeholder { color: var(--ink-muted); }
.frk-composer__listen { flex: 1; display: flex; align-items: center; gap: var(--space-3); min-height: 56px; font: 500 15px/20px var(--font-sans); }
.frk-composer.is-listening .frk-composer__bar { background: var(--surface); box-shadow: inset 0 0 0 2px var(--rec); }

@media (prefers-reduced-motion: reduce) {
  .frk-pendulum__arm.is-run, .frk-hourglass__grain, .frk-msg__caret, .frk-loader > span, .frk-timer__value.is-count { animation: none !important; }
  .frk-reveal__item, .frk-hourglass__body, .frk-tabs__ind, .frk-drawer, .frk-drawer__body { transition-duration: 1ms !important; }
  .frk-reveal:not(.is-in) .frk-reveal__item { opacity: 1 !important; transform: none !important; clip-path: none !important; filter: none !important; }
}

.frk-composer .frk-key.frk-tone--well { background: var(--surface); }
.frk-composer .frk-key.frk-tone--klein:disabled { background: var(--klein); color: var(--on-klein); opacity: .35; }

/* ================= Frekvens 4 ================= */
/* scrub rail shared by media */
.frk-scrub { position: relative; flex: 1; min-width: 80px; height: 44px; display: flex; align-items: center; cursor: pointer; touch-action: none; outline: none; }
.frk-scrub__rail { position: relative; width: 100%; height: 6px; border-radius: var(--radius-full); background: color-mix(in srgb, currentColor 22%, transparent); }
.frk-scrub__fill { position: absolute; inset: 0 auto 0 0; border-radius: inherit; background: currentColor; }
.frk-scrub__mark { position: absolute; top: 50%; width: 4px; height: 4px; margin: -2px 0 0 -2px; border-radius: var(--radius-full); background: var(--sol); }
.frk-scrub__thumb { position: absolute; top: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: var(--radius-full); background: var(--rams); transition: transform var(--dur-press, 90ms); }
.frk-scrub:active .frk-scrub__thumb { transform: scale(1.25); }
.frk-scrub:focus-visible .frk-scrub__thumb { outline: 2px solid var(--sol); outline-offset: 2px; }

/* MediaPlayer */
.frk-media { position: relative; width: 100%; overflow: hidden; border-radius: var(--radius-lg); background: #0e0e0d; color: #f2f0ea; outline: none; }
.frk-media:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-media__video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: flex; align-items: center; justify-content: center; }
.frk-media__sim { background: #0e0e0d; --paper: #f2f0ea; --dot-off: #2b2925; }
.frk-media__top { position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: center; padding: var(--space-4); background: linear-gradient(rgba(0,0,0,.55), transparent); pointer-events: none; }
.frk-media__title { font: 700 17px/22px var(--font-sans); }
.frk-media__big { position: absolute; left: 50%; top: 50%; translate: -50% -50%; }
.frk-media__bar { position: absolute; left: var(--space-2); right: var(--space-2); bottom: var(--space-2); display: flex; align-items: center; gap: var(--space-2); padding: 0 var(--space-2); border-radius: var(--radius-full);
  background: rgba(14,14,13,.78); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); transition: opacity var(--dur-base, 220ms), transform var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-media.is-playing:not(:hover):not(:focus-within) .frk-media__bar { opacity: 0; transform: translateY(8px); }
.frk-media__btn { flex: none; width: 44px; height: 44px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: var(--radius-full); background: transparent; color: inherit; cursor: pointer; font: 700 12px/1 var(--font-mono); }
.frk-media__btn:hover { background: rgba(255,255,255,.12); }
.frk-media__btn:focus-visible { outline: 2px solid var(--sol); outline-offset: 1px; }
.frk-media__cc.is-on { background: #f2f0ea; color: #111111; }
.frk-media__time { flex: none; font: 500 12px/16px var(--font-mono); font-variant-numeric: tabular-nums; }
.frk-media video::cue { font-family: var(--font-sans); background: rgba(0,0,0,.8); }

/* AudioTrack */
.frk-audio { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-3); border-radius: var(--radius-xl); }
.frk-audio__main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: var(--space-1); }
.frk-audio__head { display: flex; justify-content: space-between; gap: var(--space-2); }
.frk-audio__title { font: 700 15px/20px var(--font-sans); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.frk-audio__time { font: 500 12px/20px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink-muted); }
.frk-audio__wave { display: flex; align-items: center; gap: 2px; height: 40px; cursor: pointer; touch-action: none; outline: none; border-radius: var(--radius-sm); }
.frk-audio__wave:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-audio__wave span { flex: 1; min-height: 4px; border-radius: var(--radius-full); background: var(--dot-off); transition: background-color 80ms; }
.frk-audio__wave span.is-on { background: currentColor; }

/* Ticker */
.frk-ticker { position: relative; display: flex; align-items: center; height: 48px; border-radius: var(--radius-full); overflow: hidden; }
.frk-ticker__viewport { flex: 1; overflow: hidden; -webkit-mask-image: linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent); mask-image: linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent); }
.frk-ticker__track { display: flex; width: max-content; animation: frk-ticker 30s linear infinite; }
.frk-ticker:hover .frk-ticker__track, .frk-ticker:focus-within .frk-ticker__track, .frk-ticker.is-paused .frk-ticker__track { animation-play-state: paused; }
@keyframes frk-ticker { to { transform: translateX(-50%); } }
.frk-ticker__row { display: flex; flex: none; }
.frk-ticker__item { display: inline-flex; align-items: baseline; gap: var(--space-2); padding: 0 var(--space-3); white-space: nowrap; font: 500 14px/20px var(--font-mono); font-variant-numeric: tabular-nums; }
.frk-ticker__label { font-weight: 700; letter-spacing: .04em; }
.frk-ticker__delta.is-up { font-weight: 700; } .frk-ticker__delta.is-down { font-weight: 400; }
.frk-ticker__sep { font-size: 6px; opacity: .6; padding-left: var(--space-3); }
.frk-ticker__pause { flex: none; width: 44px; height: 44px; margin-right: 2px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: var(--radius-full); background: color-mix(in srgb, currentColor 14%, transparent); color: inherit; cursor: pointer; }
.frk-ticker__pause:focus-visible { outline: 2px solid var(--sol); outline-offset: -2px; }

/* SplitFlap */
.frk-flap__cells { display: inline-flex; gap: 3px; }
.frk-flap__cell { position: relative; display: inline-flex; align-items: center; justify-content: center; width: 1em; height: 1.4em; border-radius: 4px; background: #161615; color: #f2f0ea; font: 500 32px/1 var(--font-mono); overflow: hidden; }
.frk-flap__cell::after { content: ''; position: absolute; left: 0; right: 0; top: 50%; height: 1px; background: rgba(0,0,0,.7); }
.frk-flap__cell.is-flipping { animation: frk-flip 45ms linear; }
@keyframes frk-flip { 50% { transform: scaleY(.6); } }
.frk-flap--s .frk-flap__cell { font-size: 20px; } .frk-flap--l .frk-flap__cell { font-size: 56px; }

/* Deck */
.frk-deck { display: flex; flex-direction: column; gap: var(--space-4); outline: none; }
.frk-deck:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; border-radius: var(--radius-lg); }
.frk-deck__stack { position: relative; }
.frk-deck__card { position: absolute; inset: 0; transform-origin: 50% 100%; transition: transform var(--dur-sheet, 500ms) var(--ease-throw, ease-out); touch-action: pan-y; user-select: none; }
.frk-deck__card > * { width: 100%; height: 100%; box-sizing: border-box; }
.frk-deck__card.is-top { cursor: grab; }
.frk-deck__card.is-dragging { transition: none; cursor: grabbing; }
.frk-deck__count { font: 500 14px/18px var(--font-mono); font-variant-numeric: tabular-nums; }

/* AgentWidget */
.frk-agent { position: fixed; right: var(--space-5); bottom: var(--space-5); z-index: 130; display: flex; flex-direction: column; align-items: flex-end; gap: var(--space-3); }
.frk-agent--inline { position: relative; right: auto; bottom: auto; }
.frk-agent__launcher { width: 64px; height: 64px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: var(--radius-full); background: var(--ink); color: var(--paper); cursor: pointer;
  transition: transform var(--dur-press, 90ms) var(--ease-ui, ease-out), background-color var(--dur-fast, 150ms); }
.frk-agent__launcher:active { transform: scale(.965); }
.frk-agent__launcher.is-live { background: var(--rec); }
.frk-agent__launcher:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-agent__launcher .frk-orb circle { fill: var(--paper); }
.frk-agent__panel { width: min(380px, calc(100vw - 32px)); max-height: 600px; display: flex; flex-direction: column; border-radius: var(--radius-xl); background: var(--surface); color: var(--ink); box-shadow: 0 0 0 var(--hairline) var(--line);
  transform-origin: bottom right; opacity: 0; transform: translateY(12px) scale(.96); transition: opacity var(--dur-fast, 150ms) var(--ease-exit, ease-in), transform var(--dur-fast, 150ms) var(--ease-exit, ease-in); overflow: hidden; }
.frk-agent__panel.is-in { opacity: 1; transform: none; transition-duration: var(--dur-base, 220ms); transition-timing-function: var(--ease-ui, ease-out); }
.frk-agent__head { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-4); border-bottom: var(--hairline) solid var(--line); }
.frk-agent__who { flex: 1; display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.frk-agent__name { font: 700 16px/20px var(--font-sans); }
.frk-agent__head .frk-seg__opt { min-height: 40px; min-width: 40px; }
.frk-agent__voice { display: flex; flex-direction: column; align-items: center; gap: var(--space-4); padding: var(--space-6) var(--space-5); }
.frk-agent__transcript { margin: 0; text-align: center; font: 400 16px/22px var(--font-sans); }
.frk-agent__controls { display: flex; flex-direction: column; align-items: center; gap: var(--space-2); }
.frk-agent__hint { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-agent__chat { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-4); min-height: 320px; }
.frk-agent__log { flex: 1; display: flex; flex-direction: column; gap: var(--space-4); overflow: auto; }

/* Checkbox & Radio */
.frk-check, .frk-radio__opt { display: flex; align-items: flex-start; gap: var(--space-3); min-height: 44px; cursor: pointer; font-family: var(--font-sans); }
.frk-check.is-disabled { cursor: not-allowed; color: var(--ink-faint); }
.frk-check__box { flex: none; width: 32px; height: 32px; margin: 6px; padding: 0; display: inline-flex; align-items: center; justify-content: center; border: 2px solid var(--ink); border-radius: var(--radius-sm); background: transparent; color: transparent; cursor: inherit;
  transition: background-color var(--dur-fast, 150ms), color var(--dur-fast, 150ms), transform var(--dur-press, 90ms); }
.frk-check__box:active { transform: scale(.92); }
.frk-check.is-on .frk-check__box, .frk-check.is-mixed .frk-check__box { background: var(--ink); color: var(--paper); }
.frk-check__box:disabled { border-color: var(--ink-faint); }
.frk-check__box:focus-visible, .frk-radio__opt:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-check__text { display: flex; flex-direction: column; padding-top: 10px; gap: 2px; text-align: left; }
.frk-check__label { font: 500 16px/22px var(--font-sans); }
.frk-check__hint { font: 13px/18px var(--font-sans); color: var(--ink-muted); }
.frk-radio { display: flex; flex-direction: column; gap: var(--space-1); }
.frk-radio--row { flex-direction: row; flex-wrap: wrap; gap: var(--space-4); }
.frk-radio__opt { padding: 0; border: 0; background: none; color: inherit; border-radius: var(--radius-md); }
.frk-radio__opt:disabled { color: var(--ink-faint); cursor: not-allowed; }
.frk-radio__mark { flex: none; width: 32px; height: 32px; margin: 6px; box-sizing: border-box; border: 2.5px solid currentColor; border-radius: var(--radius-full); transition: border-width var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-radio__opt.is-on .frk-radio__mark { border-width: 16px; }

/* Calendar */
.frk-cal { display: flex; flex-direction: column; gap: var(--space-3); max-width: 420px; }
.frk-cal__head { display: flex; justify-content: space-between; align-items: center; }
.frk-cal__title { font: 700 20px/24px var(--font-sans); letter-spacing: -.01em; }
.frk-cal__view { height: 44px; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-full); background: transparent; color: var(--ink); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; cursor: pointer; }
.frk-cal__view:hover { background: var(--well); }
.frk-cal__view:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-cal__dow, .frk-cal__grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: var(--space-1); }
.frk-cal__dow span { text-align: center; font: 500 11px/14px var(--font-mono); color: var(--ink-muted); }
.frk-cal__day { position: relative; aspect-ratio: 1; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: var(--radius-full); background: var(--surface); color: var(--ink);
  font: 500 16px/1 var(--font-sans); font-variant-numeric: tabular-nums; cursor: pointer; transition: background-color var(--dur-fast, 150ms), color var(--dur-fast, 150ms), transform var(--dur-press, 90ms); }
.frk-cal__day:active { transform: scale(.94); }
.frk-cal__day:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-cal__day.is-today { box-shadow: inset 0 0 0 2px var(--ink); }
.frk-cal__day.is-past { background: transparent; color: var(--ink-muted); }
.frk-cal__day.is-out { background: transparent; color: var(--ink-muted); }
.frk-cal__day.is-sel { background: var(--ink); color: var(--paper); }
.frk-cal__day.has-mark::after { content: ''; position: absolute; bottom: 6px; width: 5px; height: 5px; border-radius: var(--radius-full); background: var(--rams); }
.frk-cal__day.is-sel.has-mark::after { background: var(--sol); }
.frk-cal--week .frk-cal__day { font-size: 18px; }

/* Banner */
.frk-banner { display: flex; align-items: center; gap: var(--space-3); min-height: 56px; padding: var(--space-2) var(--space-2) var(--space-2) var(--space-4); border-radius: var(--radius-md); animation: frk-in var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-banner__icon { flex: none; display: inline-flex; }
.frk-banner__text { flex: 1; display: flex; flex-direction: column; font: 400 15px/20px var(--font-sans); padding: var(--space-1) 0; }
.frk-banner__text strong { font-weight: 700; }
.frk-banner__action { flex: none; height: 44px; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-full); background: currentColor; cursor: pointer; font: 700 14px/18px var(--font-sans); }
.frk-banner__action { background: transparent; color: inherit; box-shadow: inset 0 0 0 2px currentColor; }
.frk-banner__action:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
.frk-banner .frk-toast__close { width: 44px; height: 44px; }

/* Skeleton */
.frk-skel { display: flex; flex-direction: column; gap: var(--space-2); }
.frk-skel__line, .frk-skel__tile, .frk-skel__circle { display: block; background-image: radial-gradient(circle, var(--dot-off) 2.2px, transparent 2.6px); background-size: 8px 8px; border-radius: var(--radius-sm);
  -webkit-mask-image: linear-gradient(90deg, #000 30%, rgba(0,0,0,.35) 50%, #000 70%); mask-image: linear-gradient(90deg, #000 30%, rgba(0,0,0,.35) 50%, #000 70%); -webkit-mask-size: 300% 100%; mask-size: 300% 100%; animation: frk-skel 1.6s linear infinite; }
.frk-skel__line { height: 16px; }
.frk-skel__tile { height: 160px; width: 100%; border-radius: var(--radius-lg); }
.frk-skel__circle { width: 56px; height: 56px; border-radius: var(--radius-full); }
@keyframes frk-skel { from { -webkit-mask-position: 100% 0; mask-position: 100% 0; } to { -webkit-mask-position: -50% 0; mask-position: -50% 0; } }

/* EmptyState */
.frk-empty { display: flex; flex-direction: column; align-items: center; gap: var(--space-3); padding: var(--space-6) var(--space-5); text-align: center; }
.frk-empty__title { font: 700 20px/24px var(--font-sans); }
.frk-empty__text { margin: 0; max-width: 32ch; font: 400 15px/21px var(--font-sans); color: var(--ink-muted); }
.frk-empty--compact { padding: var(--space-4); gap: var(--space-2); }
.frk-empty--compact .frk-empty__title { font-size: 16px; }

/* Badge */
.frk-badge-wrap { position: relative; display: inline-flex; }
.frk-badge { position: absolute; top: -6px; right: -8px; min-width: 20px; height: 20px; padding: 0 5px; box-sizing: border-box; border-radius: var(--radius-full); font: 700 11px/20px var(--font-mono); text-align: center; box-shadow: 0 0 0 2px var(--paper); animation: frk-badge var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-badge.is-dot { min-width: 10px; width: 10px; height: 10px; padding: 0; top: -2px; right: -2px; }
@keyframes frk-badge { from { transform: scale(0); } }

/* TabBar */
.frk-tabbar { display: inline-flex; gap: 4px; padding: 6px; border-radius: var(--radius-full); background: var(--ink); }
.frk-tabbar__item { display: inline-flex; align-items: center; gap: var(--space-2); height: 48px; min-width: 48px; padding: 0 12px; border: 0; border-radius: var(--radius-full); background: transparent; color: var(--paper); cursor: pointer;
  transition: background-color var(--dur-base, 220ms) var(--ease-travel, ease), padding var(--dur-base, 220ms) var(--ease-travel, ease); }
.frk-tabbar__item:focus-visible { outline: 2px solid var(--sol); outline-offset: 2px; }
.frk-tabbar__label { max-width: 0; overflow: hidden; white-space: nowrap; font: 700 14px/18px var(--font-sans); transition: max-width var(--dur-base, 220ms) var(--ease-travel, ease); }
.frk-tabbar__item.is-on { background: var(--paper); color: var(--ink); padding: 0 var(--space-4) 0 12px; }
.frk-tabbar__item.is-on .frk-tabbar__label { max-width: 120px; }
.frk-tabbar .frk-badge { box-shadow: 0 0 0 2px var(--ink); }

/* TopBar */
.frk-topbar { display: flex; flex-direction: column; gap: var(--space-4); }
.frk-topbar__row { display: grid; grid-template-columns: 56px 1fr auto; align-items: center; gap: var(--space-2); min-height: 56px; }
.frk-topbar__spacer { width: 56px; }
.frk-topbar__title { margin: 0; text-align: center; font: 700 17px/22px var(--font-sans); }
.frk-topbar__actions { display: flex; gap: var(--space-2); justify-content: flex-end; min-width: 56px; }

/* Steps */
.frk-steps { display: flex; margin: 0; padding: 0; list-style: none; }
.frk-steps__item { position: relative; flex: 1; display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); }
.frk-steps__item::before { content: ''; position: absolute; top: 11px; left: 30px; right: 8px; height: 2px; background: var(--dot-off); }
.frk-steps__item:last-child::before { display: none; }
.frk-steps__item.is-full::before { background: var(--ink); }
.frk-steps__label { font: 500 13px/18px var(--font-sans); color: var(--ink-muted); padding-right: var(--space-2); }
.frk-steps__item.is-partial .frk-steps__label { color: var(--ink); font-weight: 700; }

/* Tooltip */
.frk-tip-wrap { position: relative; display: inline-flex; }
.frk-tip { position: absolute; z-index: 60; left: 50%; bottom: calc(100% + 8px); translate: -50% 0; width: max-content; max-width: 240px; padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm); background: var(--ink); color: var(--paper);
  font: 500 13px/18px var(--font-sans); pointer-events: none; opacity: 0; transform: translateY(4px); transition: opacity var(--dur-fast, 150ms), transform var(--dur-fast, 150ms) var(--ease-ui, ease-out); }
.frk-tip--bottom { bottom: auto; top: calc(100% + 8px); transform: translateY(-4px); }
.frk-tip.is-in { opacity: 1; transform: none; }

/* Avatar */
.frk-avatar { position: relative; flex: none; display: inline-flex; align-items: center; justify-content: center; border-radius: var(--radius-full); font-family: var(--font-sans); font-weight: 800; letter-spacing: -.02em; }
.frk-avatar__img { width: 100%; height: 100%; border-radius: inherit; object-fit: cover; }
.frk-avatar__status { position: absolute; right: 0; bottom: 0; width: 28%; height: 28%; min-width: 10px; min-height: 10px; border-radius: var(--radius-full); box-shadow: 0 0 0 2px var(--surface); background: var(--dot-off); }
.frk-avatar__status.is-online { background: var(--verde); } .frk-avatar__status.is-live { background: var(--rec); animation: frk-blink 1.2s steps(2, jump-none) infinite; } .frk-avatar__status.is-away { background: var(--sol); }

/* LineChart */
.frk-line { margin: 0; }
.frk-line svg { display: block; overflow: visible; }
.frk-line__path { fill: none; stroke: var(--ink); stroke-width: 2.5; stroke-linecap: round; }
.frk-line__path.is-future { stroke-width: 1.5; opacity: .45; }
.frk-line__now { stroke: var(--ink); stroke-width: 1.5; }
.frk-line__ring { fill: none; stroke: var(--ink); stroke-width: 1.5; }
.frk-line__dot { fill: var(--ink); }
.frk-line__lbl { font: 500 11px var(--font-mono); fill: var(--ink-muted); }
.frk-line__lbl.is-now { fill: var(--ink); font-weight: 700; }
.frk-line--rams .frk-line__path:not(.is-future) { stroke: var(--rams); }
.frk-line--klein .frk-line__path:not(.is-future) { stroke: var(--klein-ink); }
.frk-line__cap { margin-top: var(--space-2); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }

@media (prefers-reduced-motion: reduce) {
  .frk-ticker__track { animation: none !important; }
  .frk-ticker__viewport { overflow-x: auto; }
  .frk-ticker__row[aria-hidden] { display: none; }
  .frk-skel__line, .frk-skel__tile, .frk-skel__circle, .frk-flap__cell, .frk-avatar__status { animation: none !important; }
  .frk-deck__card, .frk-agent__panel, .frk-tabbar__item, .frk-tabbar__label, .frk-radio__mark { transition-duration: 1ms !important; }
}

/* reflow down to 320px */
.frk-composer, .frk-suggest, .frk-cal, .frk-pager, .frk-tabs, .frk-media, .frk-audio__main { min-width: 0; max-width: 100%; }
.frk-cal__day { min-height: 0; min-width: 0; }
.frk-cal__head { gap: var(--space-2); flex-wrap: wrap; }

.frk-sheet__panel { width: 100%; max-width: 560px; margin: 0 auto; box-sizing: border-box; }

/* ================= Frekvens 5 ================= */
/* Heatmap */
.frk-heat { margin: 0; max-width: 100%; }
.frk-heat svg { display: block; }
.frk-heat circle { fill: var(--dot-off); }
.frk-heat circle.is-on { fill: var(--ink); }
.frk-heat--rams circle.is-on { fill: var(--rams); } .frk-heat--klein circle.is-on { fill: var(--klein-ink); } .frk-heat--verde circle.is-on { fill: var(--verde); }

/* SplitBar */
.frk-split { display: flex; flex-direction: column; gap: var(--space-3); }
.frk-split__bar { display: flex; gap: 4px; height: 40px; }
.frk-split__bar span { flex-basis: 0; min-width: 8px; border-radius: var(--radius-full); }
.frk-split__legend { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-5); margin: 0; padding: 0; list-style: none; font: 500 13px/18px var(--font-sans); }
.frk-split__legend li { display: inline-flex; align-items: center; gap: var(--space-2); }
.frk-split__legend b { font: 500 13px/18px var(--font-mono); }
.frk-split__sw { width: 10px; height: 10px; border-radius: var(--radius-full); }
.frk-split--columns { flex-direction: row; gap: var(--space-2); width: 100%; }
.frk-split__col { min-width: 96px; }
.frk-split__col { flex: 1; position: relative; display: flex; flex-direction: column; justify-content: flex-end; border-radius: 40px; background: var(--ink); padding: 6px; box-sizing: border-box; }
.frk-split__fill { position: relative; border-radius: 34px; display: flex; align-items: flex-start; justify-content: center; padding-top: var(--space-3); box-sizing: border-box; transition: height var(--dur-grow, 640ms) var(--ease-arrive, ease-out); }
.frk-split__pc { font: 400 24px/1 var(--font-sans); letter-spacing: -.02em; }
.frk-split__lbl { position: absolute; left: 0; right: 0; bottom: 10px; text-align: center; font: 500 12px/16px var(--font-sans); }

/* Sparkline */
.frk-spark { display: inline-block; vertical-align: middle; overflow: visible; }
.frk-spark polyline { fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.frk-spark circle { fill: var(--ink); }
.frk-spark--rams polyline { stroke: var(--rams); } .frk-spark--rams circle { fill: var(--rams); }
.frk-spark--klein polyline { stroke: var(--klein-ink); } .frk-spark--klein circle { fill: var(--klein-ink); }

/* ClickWheel */
.frk-wheelpad { position: relative; border-radius: var(--radius-full); box-shadow: inset 0 0 0 var(--hairline) var(--line); }
.frk-wheelpad__ring { position: absolute; inset: 0; border-radius: inherit; touch-action: none; cursor: grab; outline: none; }
.frk-wheelpad__ring:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-wheelpad__ticks { pointer-events: none; }
.frk-wheelpad__ticks { position: absolute; inset: 10px; border-radius: inherit; background: repeating-conic-gradient(from 0deg, var(--dot-off) 0 1.2deg, transparent 1.2deg 15deg); -webkit-mask: radial-gradient(circle, transparent 60%, #000 61%, #000 70%, transparent 71%); mask: radial-gradient(circle, transparent 60%, #000 61%, #000 70%, transparent 71%); transition: transform 80ms linear; }
.frk-wheelpad__btn { position: absolute; width: 56px; height: 44px; display: inline-flex; align-items: center; justify-content: center; border: 0; background: transparent; color: inherit; cursor: pointer; font: 700 11px/14px var(--font-mono); letter-spacing: .08em; border-radius: var(--radius-full); }
.frk-wheelpad__btn:active { transform: scale(.94); }
.frk-wheelpad__btn--top { top: 8px; left: 50%; margin-left: -28px; } .frk-wheelpad__btn--bottom { bottom: 8px; left: 50%; margin-left: -28px; }
.frk-wheelpad__btn--left { left: 4px; top: 50%; margin-top: -22px; } .frk-wheelpad__btn--right { right: 4px; top: 50%; margin-top: -22px; }
.frk-wheelpad__center { position: absolute; left: 50%; top: 50%; width: 36%; height: 36%; translate: -50% -50%; border: 0; border-radius: var(--radius-full); background: var(--paper); box-shadow: inset 0 0 0 var(--hairline) var(--line); cursor: pointer; transition: transform var(--dur-press, 90ms); }
.frk-wheelpad__center:active { transform: scale(.94); box-shadow: var(--shadow-press); }

/* DiscCarousel */
.frk-discs-wrap { display: flex; flex-direction: column; gap: var(--space-3); }
.frk-discs { position: relative; display: flex; justify-content: center; outline: none; overflow: hidden; }
