.frk-disc__vinyl { position: relative; display: flex; align-items: center; justify-content: center; width: 100%; height: 100%; border-radius: var(--radius-full); background: repeating-radial-gradient(circle, #151514 0 2px, #222220 2px 3px); box-shadow: 0 0 0 var(--hairline) rgba(255,255,255,.08) inset; }
