.frk-discs__sub { font: 500 14px/18px var(--font-sans); color: var(--ink-muted); }

/* Sidebar */
.frk-side { display: flex; flex-direction: column; gap: var(--space-5); width: 248px; height: 100%; padding: var(--space-4) var(--space-3); box-sizing: border-box; border-radius: var(--radius-lg); transition: width var(--dur-base, 220ms) var(--ease-travel, ease); overflow: hidden; }
