.frk-side.is-collapsed .frk-side__head { padding: 0; }
.frk-side__toggle { flex: none; width: 44px; height: 44px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: var(--radius-full); background: transparent; color: inherit; cursor: pointer; }
.frk-side__toggle:hover { background: var(--well); }
.frk-side__toggle:focus-visible, .frk-side__item:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-side__sec ul { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 2px; }
.frk-side__label { display: block; padding: 0 var(--space-3) var(--space-2); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-side__item { display: flex; align-items: center; gap: var(--space-3); width: 100%; min-height: 44px; padding: 0 var(--space-3); border: 0; border-radius: var(--radius-md); background: transparent; color: inherit; cursor: pointer; font: 500 15px/20px var(--font-sans); text-align: left; transition: background-color var(--dur-fast, 150ms); }
.frk-side.is-collapsed .frk-side__item { width: 52px; justify-content: center; padding: 0; }
.frk-side__item:hover { background: var(--well); }
.frk-side__item.is-on { background: var(--ink); color: var(--paper); }
.frk-side__text { flex: 1; white-space: nowrap; }
.frk-side__count { font: 500 12px/16px var(--font-mono); color: var(--ink-muted); }
.frk-side__item.is-on .frk-side__count { color: inherit; }
.frk-side__count.is-alert { min-width: 22px; padding: 0 6px; border-radius: var(--radius-full); background: var(--rec); color: var(--on-rec); text-align: center; line-height: 22px; }
.frk-side__foot { margin-top: auto; }
.frk-side .frk-badge { box-shadow: none; }

/* DataTable */
.frk-table-wrap { overflow: auto; max-width: 100%; border-radius: var(--radius-lg); background: var(--surface); outline: none; }
.frk-table-wrap:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
