.frk-table__check { width: 44px; padding-right: 0 !important; }
.frk-table__check .frk-check { min-height: 0; }
.frk-table__check .frk-check__box { width: 24px; height: 24px; margin: 0; }
.frk-table__check .frk-check__text { display: none; }
.frk-table__sort { display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 0; border: 0; background: none; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; cursor: pointer; }
.frk-table__sort.is-on { color: var(--ink); }
.frk-table__sort:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
.frk-table__arrow { font-size: 9px; }
.frk-table__bar { display: block; width: 80px; height: 6px; border-radius: var(--radius-full); background: var(--well); overflow: hidden; }
.frk-table__bar span { display: block; height: 100%; background: var(--ink); border-radius: inherit; }
.frk-table__who { display: inline-flex; align-items: center; gap: var(--space-2); }
.frk-table .frk-chip { height: 24px; }

/* CommandBar */
.frk-cmd { position: fixed; inset: 0; z-index: 140; display: flex; justify-content: center; align-items: flex-start; padding-top: 12vh; }
.frk-cmd--inline { position: absolute; padding-top: var(--space-8); }
.frk-cmd__scrim { position: absolute; inset: 0; background: rgba(0,0,0,.35); opacity: 0; transition: opacity var(--dur-base, 220ms); }
.frk-cmd.is-in .frk-cmd__scrim { opacity: 1; }
.frk-cmd__panel { position: relative; width: min(560px, calc(100% - 32px)); border-radius: var(--radius-lg); background: var(--ink); color: var(--paper); overflow: hidden;
  opacity: 0; transform: translateY(-8px) scale(.98); transition: opacity var(--dur-fast, 150ms) var(--ease-exit, ease-in), transform var(--dur-fast, 150ms) var(--ease-exit, ease-in); }
.frk-cmd.is-in .frk-cmd__panel { opacity: 1; transform: none; transition-duration: var(--dur-base, 220ms); transition-timing-function: var(--ease-ui, ease-out); }
.frk-cmd__search { display: flex; align-items: center; gap: var(--space-3); padding: 0 var(--space-4); border-bottom: var(--hairline) solid color-mix(in srgb, var(--paper) 18%, transparent); }
.frk-cmd__input { flex: 1; height: 60px; border: 0; outline: none; background: transparent; color: inherit; font: 400 18px/24px var(--font-sans); }
.frk-cmd__input::placeholder { color: color-mix(in srgb, var(--paper) 72%, transparent); }
.frk-cmd__kbd { font: 500 11px/14px var(--font-mono); letter-spacing: .06em; padding: 3px 6px; border-radius: 4px; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--paper) 40%, transparent); }
.frk-cmd__list { max-height: 360px; overflow: auto; padding: 6px; }
.frk-cmd__group { padding: var(--space-3) var(--space-3) var(--space-1); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: color-mix(in srgb, var(--paper) 78%, transparent); }
.frk-cmd__item { display: flex; align-items: center; gap: var(--space-3); min-height: 48px; padding: 0 var(--space-3); border-radius: var(--radius-md); cursor: pointer; font: 500 15px/20px var(--font-sans); }
.frk-cmd__item > span:nth-child(2) { flex: 1; }
.frk-cmd__item.is-active { background: color-mix(in srgb, var(--paper) 14%, transparent); }
.frk-cmd__empty { padding: var(--space-5); text-align: center; font: 400 15px/20px var(--font-sans); }

/* Notch */
.frk-notch { position: fixed; top: 6px; left: 50%; translate: -50% 0; z-index: 150; display: flex; flex-direction: column; align-items: stretch; width: 240px; border-radius: 22px; background: #000; color: #f2f0ea; overflow: hidden;
  transition: width var(--dur-sheet, 500ms) cubic-bezier(.34, 1.36, .64, 1), border-radius var(--dur-sheet, 500ms) cubic-bezier(.34, 1.36, .64, 1); --paper: #f2f0ea; --dot-off: #2b2925; }
.frk-notch--inline { position: relative; top: 0; left: auto; translate: none; margin: 0 auto; }
.frk-notch.is-open { width: 440px; border-radius: 32px; }
.frk-notch__pill { display: flex; align-items: center; gap: var(--space-2); height: 36px; padding: 0 var(--space-3); border: 0; background: transparent; color: inherit; cursor: pointer; }
.frk-notch__pill:focus-visible { outline: 2px solid var(--sol); outline-offset: -2px; border-radius: 22px; }
.frk-notch__peek { flex: 1; text-align: left; font: 500 12px/16px var(--font-mono); letter-spacing: .06em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.frk-notch__led { width: 8px; height: 8px; border-radius: var(--radius-full); background: #3a3732; }
.frk-notch__led.is-listening { background: var(--rec); animation: frk-blink 1.2s steps(2, jump-none) infinite; } .frk-notch__led.is-thinking { background: var(--sol); } .frk-notch__led.is-speaking { background: var(--rams); } .frk-notch__led.is-done { background: #2f7d52; }
