.frk-notch__body > * { overflow: hidden; }
.frk-notch__body { display: grid; }
.frk-notch__row, .frk-notch__prog, .frk-notch__actions { min-height: 0; }
.frk-notch__row { display: flex; align-items: center; gap: var(--space-4); padding: var(--space-2) var(--space-5) 0; opacity: 0; transition: opacity var(--dur-fast, 150ms); }
.frk-notch.is-open .frk-notch__row, .frk-notch.is-open .frk-notch__actions, .frk-notch.is-open .frk-notch__prog { opacity: 1; transition-delay: 160ms; }
.frk-notch__text { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.frk-notch__name { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: #bdb8af; }
.frk-notch__line { font: 500 16px/22px var(--font-sans); }
.frk-notch__prog { height: 4px; margin: var(--space-3) var(--space-5) 0; border-radius: var(--radius-full); background: #2b2925; opacity: 0; }
.frk-notch__prog span { display: block; height: 100%; border-radius: inherit; background: var(--rams); transition: width var(--dur-base, 220ms); }
.frk-notch__actions { display: flex; gap: var(--space-2); padding: var(--space-3) var(--space-4) var(--space-4); opacity: 0; transition: opacity var(--dur-fast, 150ms); }
.frk-notch__act { display: inline-flex; align-items: center; gap: 6px; height: 40px; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-full); background: #1e1d1b; color: inherit; font: 700 13px/16px var(--font-sans); cursor: pointer; }
.frk-notch__act.is-main { background: #f2f0ea; color: #111111; }
.frk-notch__act:focus-visible { outline: 2px solid var(--sol); outline-offset: 2px; }

/* Viewport3D */
.frk-3d { display: flex; flex-direction: column; gap: var(--space-3); }
.frk-3d__stage { position: relative; display: flex; align-items: center; justify-content: center; perspective: 900px; border-radius: var(--radius-lg); background: var(--surface); overflow: hidden; cursor: grab; touch-action: none; outline: none; }
.frk-3d__stage:active { cursor: grabbing; }
.frk-3d__stage:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-3d__cam { position: relative; width: 0; height: 0; transform-style: preserve-3d; transition: transform 60ms linear; }
.frk-3d__floor { position: absolute; left: -200px; top: -200px; width: 400px; height: 400px; transform: translateY(60px) rotateX(90deg); background-image: radial-gradient(circle, var(--ink-muted) 1.4px, transparent 1.8px); background-size: 20px 20px; -webkit-mask: radial-gradient(circle, #000 40%, transparent 70%); mask: radial-gradient(circle, #000 40%, transparent 70%); }
.frk-3d__obj { position: absolute; left: 0; top: 0; transform-style: preserve-3d; }
.frk-3d__face { position: absolute; left: 0; top: 0; translate: -50% -50%; border-radius: 10px; box-shadow: inset 0 0 0 1px rgba(0,0,0,.12); backface-visibility: visible; }
.frk-3d__gizmo { position: absolute; right: 16px; bottom: 16px; width: 48px; height: 48px; perspective: 300px; }
.frk-3d__gizmo span { position: absolute; left: 24px; top: 24px; transform-style: preserve-3d; }
.frk-3d__gizmo i { position: absolute; left: 0; top: 0; width: 22px; height: 3px; border-radius: 2px; transform-origin: 0 50%; }
.frk-3d__gizmo .x { background: var(--rams); } .frk-3d__gizmo .y { background: var(--verde); transform: rotateZ(-90deg); } .frk-3d__gizmo .z { background: var(--klein-ink); transform: rotateY(-90deg); }
.frk-3d__bar { display: flex; justify-content: space-between; align-items: center; gap: var(--space-3); flex-wrap: wrap; }
.frk-3d__read { font: 500 12px/16px var(--font-mono); font-variant-numeric: tabular-nums; color: var(--ink-muted); }

/* NumPad */
.frk-numpad { display: flex; flex-direction: column; gap: var(--space-4); width: 100%; max-width: 360px; }
.frk-numpad__display { display: flex; align-items: baseline; justify-content: center; gap: var(--space-2); font: 400 72px/1 var(--font-sans); letter-spacing: -.04em; font-variant-numeric: tabular-nums; min-height: 80px; }
.frk-numpad__display.is-empty { color: var(--ink-muted); }
.frk-numpad__cur { font-size: 32px; color: var(--ink-muted); }
.frk-numpad__hint { text-align: center; font: 500 13px/18px var(--font-sans); color: var(--ink-muted); margin-top: calc(var(--space-3) * -1); }
.frk-numpad__keys { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--hairline); background: var(--line); border-radius: var(--radius-lg); overflow: hidden; }
.frk-numpad__key { height: 68px; border: 0; background: var(--surface); color: var(--ink); font: 400 30px/1 var(--font-sans); cursor: pointer; display: inline-flex; align-items: center; justify-content: center; transition: background-color var(--dur-press, 90ms); }
.frk-numpad__key:active { background: var(--well); box-shadow: var(--shadow-press); }
.frk-numpad__key:focus-visible { outline: 2px solid var(--focus); outline-offset: -3px; }

/* HourStrip */
.frk-hours { margin: 0; display: flex; flex-direction: column; gap: var(--space-2); }
.frk-hours__now { display: flex; flex-direction: column; gap: 2px; }
.frk-hours__price { font: 400 48px/1 var(--font-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.frk-hours__price small { font: 500 13px/18px var(--font-mono); letter-spacing: 0; color: var(--ink-muted); }
.frk-hours__bars { display: flex; align-items: flex-end; gap: 3px; height: 96px; }
.frk-hours__bar { flex: 1; min-width: 4px; border-radius: var(--radius-full); transition: height var(--dur-grow, 640ms) var(--ease-arrive, ease-out); }
.frk-hours__bar.is-past { opacity: .35; }
.frk-hours__bar.is-now { box-shadow: 0 0 0 2px var(--paper), 0 0 0 4px var(--ink); }
.frk-hours__axis { display: flex; justify-content: space-between; font: 500 11px/14px var(--font-mono); color: var(--ink-muted); }
.frk-hours__legend { display: flex; gap: var(--space-4); font: 500 12px/16px var(--font-sans); }
.frk-hours__legend span { display: inline-flex; align-items: center; gap: 6px; }
.frk-hours__legend i { width: 10px; height: 10px; border-radius: var(--radius-full); }

/* PaymentCard */
.frk-card { position: relative; width: 100%; max-width: 340px; aspect-ratio: 85.6 / 54; padding: var(--space-5); box-sizing: border-box; border-radius: 20px; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; }
.frk-card__top { display: flex; justify-content: space-between; align-items: flex-start; }
.frk-card__brand { font: 800 20px/1 var(--font-sans); letter-spacing: -.02em; }
.frk-card__chip circle { fill: currentColor; opacity: .85; }
.frk-card__num { font: 500 20px/1 var(--font-mono); letter-spacing: .08em; }
.frk-card__bottom { display: flex; justify-content: space-between; font: 500 12px/16px var(--font-mono); letter-spacing: .06em; text-transform: uppercase; }
.frk-card__frost { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: color-mix(in srgb, var(--surface) 78%, transparent); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); color: var(--ink); }

/* Recorder */
.frk-rec { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-4); border-radius: var(--radius-xl); background: var(--well); }
.frk-rec__deck { display: flex; align-items: center; gap: var(--space-4); }
.frk-rec__reel { position: relative; flex: none; width: 168px; height: 168px; border-radius: var(--radius-full); background: var(--surface); box-shadow: inset 0 0 0 var(--hairline) var(--line); }
.frk-rec__reel::before { content: ''; position: absolute; inset: 12px; border-radius: inherit; background-image: radial-gradient(circle, var(--dot-off) 1.6px, transparent 2px); background-size: 12px 12px; -webkit-mask: radial-gradient(circle, transparent 34%, #000 35%); mask: radial-gradient(circle, transparent 34%, #000 35%); }
.frk-rec__hub { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; translate: -50% -50%; border-radius: var(--radius-full); background: var(--paper); box-shadow: inset 0 0 0 var(--hairline) var(--line); }
.frk-rec__line { position: absolute; left: 50%; top: 10px; bottom: 50%; width: 2px; margin-left: -1px; background: var(--rams); transform-origin: 50% 100%; }
.frk-rec.is-rec .frk-rec__line, .frk-rec.is-rec .frk-rec__reel::before { animation: frk-spin 3s linear infinite; }
.frk-rec__side { flex: 1; display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.frk-rec__lcd { align-self: flex-start; padding: 4px 8px; border-radius: var(--radius-sm); background: var(--ink); color: var(--paper); }
.frk-rec__lcd .frk-led__text { color: var(--paper); }
.frk-rec__time { font: 800 44px/1 var(--font-dot); font-variant-numeric: tabular-nums; }
.frk-rec__takes { display: flex; flex-direction: column; gap: var(--space-2); }

/* CaptureKey */
.frk-capture { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-3); }
.frk-capture__key { position: relative; width: 96px; height: 96px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: 32px; background: var(--ink); cursor: pointer; touch-action: none; user-select: none; transition: transform var(--dur-press, 90ms) var(--ease-ui, ease-out), border-radius var(--dur-base, 220ms) var(--ease-ui, ease-out), background-color var(--dur-fast, 150ms); }
.frk-capture__key:active { transform: scale(.94); }
.frk-capture__key:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-capture__dot { width: 28px; height: 28px; border-radius: var(--radius-full); background: var(--paper); transition: transform var(--dur-base, 220ms) var(--ease-ui, ease-out); }
.frk-capture.is-flash .frk-capture__dot { transform: scale(1.6); }
.frk-capture.is-voice .frk-capture__key { background: var(--rec); border-radius: var(--radius-full); }
.frk-capture.is-saved .frk-capture__key { background: var(--verde); }
.frk-capture__label { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); text-align: center; min-height: 14px; }

/* Viewfinder */
.frk-cam { position: relative; width: 100%; max-width: 380px; display: flex; flex-direction: column; border-radius: var(--radius-xl); background: #0e0e0d; color: #f2f0ea; overflow: hidden; --paper: #f2f0ea; --dot-off: #2b2925; --ink: #f2f0ea; --ink-muted: #bdb8af; --well: #2b2925; --surface: #1b1a18; }
