  background-image: radial-gradient(circle, var(--dot-off) 1.4px, transparent 1.8px); background-size: 12px 12px; box-shadow: inset 0 0 0 2px var(--line); transition: box-shadow var(--dur-fast, 150ms), background-color var(--dur-fast, 150ms); }
