.frk-file { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-2) var(--space-2) var(--space-2) var(--space-3); border-radius: var(--radius-md); background: var(--surface); animation: frk-in var(--dur-base, 220ms) var(--ease-ui, ease-out); }
