/* ChoiceCards */
.frk-choices { display: grid; gap: var(--space-2); }
.frk-choice { display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); padding: var(--space-4); border: 0; border-radius: var(--radius-lg); background: var(--surface); color: var(--ink); text-align: left; cursor: pointer; box-shadow: inset 0 0 0 2px transparent; font-family: var(--font-sans);
  transition: box-shadow var(--dur-fast, 150ms), transform var(--dur-press, 90ms); }
