html[data-theme="dark"] .frk-vu__face { fill: #f1ece2; }
.frk-vu__num { font: 600 12px var(--font-mono); fill: #1b1915; }
.frk-vu__tick { stroke: #1b1915; stroke-width: 1.2; } .frk-vu__tick.is-red { stroke: #c4361d; }
.frk-vu__num.is-red { fill: #c4361d; }
.frk-vu__needle { stroke: #1b1915; stroke-width: 2; stroke-linecap: round; transition: all 60ms linear; }
.frk-vu__pin { fill: #1b1915; }
.frk-vu__label { font: 500 10px var(--font-mono); letter-spacing: .06em; fill: #4d4740; }
.frk-vu__peak { fill: #d9d2c4; transition: fill var(--dur-fast, 150ms); }
.frk-vu__peak.is-on { fill: #e2301b; }

/* RotarySelector */
.frk-rotary { position: relative; flex: none; }
.frk-rotary__lbl { position: absolute; font: 500 11px/13px var(--font-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--ink-muted); white-space: nowrap; cursor: pointer; transition: color var(--dur-fast, 150ms); }
.frk-rotary__lbl.is-on { color: var(--ink); font-weight: 700; }
.frk-rotary__knob { position: absolute; inset: 24%; border-radius: var(--radius-full); background: var(--ink); cursor: grab; touch-action: none;
  box-shadow: inset 0 0 0 6px color-mix(in srgb, var(--paper) 10%, transparent), 0 2px 0 var(--line); }
.frk-rotary__knob:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
.frk-rotary__bar { position: absolute; left: calc(50% - 3px); top: 8%; width: 6px; height: 42%; border-radius: 3px; background: var(--paper); transform-origin: 50% 100%; transition: transform var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-rotary__mark { display: none; }

/* Fader */
.frk-fader { display: inline-flex; flex-direction: column; align-items: center; gap: var(--space-2); }
.frk-fader__track { position: relative; width: 56px; touch-action: none; cursor: ns-resize; border-radius: var(--radius-sm); }
.frk-fader__track:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
.frk-fader__slot { position: absolute; left: calc(50% - 3px); top: 0; bottom: 0; width: 6px; border-radius: 3px; background: var(--ink); }
.frk-fader__tick { position: absolute; left: 6px; width: 10px; height: 1px; background: var(--ink-muted); }
.frk-fader__tick:nth-of-type(odd) { width: 14px; }
.frk-fader__cap { position: absolute; left: 4px; right: 4px; height: 28px; border-radius: 6px; box-shadow: 0 2px 0 rgba(0,0,0,.25), inset 0 -3px 0 rgba(0,0,0,.18); transition: bottom var(--dur-press, 90ms) linear; }
.frk-fader__cap::after { content: ''; position: absolute; left: 6px; right: 6px; top: 13px; height: 2px; background: currentColor; opacity: .6; }
.frk-fader__val { font: 700 16px/20px var(--font-mono); font-variant-numeric: tabular-nums; }
.frk-fader__lbl { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }

/* Keycap */
.frk-keycap { position: relative; min-width: 56px; min-height: 56px; padding: 0; border: 0; border-radius: var(--radius-md); cursor: pointer; font: 500 20px/1 var(--font-sans);
  background: color-mix(in srgb, var(--surface) 80%, #000 20%); color: var(--ink); box-shadow: 0 3px 0 rgba(0,0,0,.18);
  transition: transform var(--dur-press, 90ms) var(--ease-ui, ease-out), box-shadow var(--dur-press, 90ms); -webkit-tap-highlight-color: transparent; }
.frk-keycap__top { position: absolute; inset: 4px 4px 8px; border-radius: 12px; background: var(--surface); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 2px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.5), inset 0 -2px 6px rgba(0,0,0,.06); }
.frk-keycap:active { transform: translateY(2px); box-shadow: 0 1px 0 rgba(0,0,0,.18); }
.frk-keycap:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-keycap__sub { font: 500 9px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-keycap--ink { background: #000; } .frk-keycap--ink .frk-keycap__top { background: var(--ink); color: var(--paper); }
html[data-theme="dark"] .frk-keycap--ink { background: #8a8378; }
.frk-keycap--rams { background: color-mix(in srgb, var(--rams) 70%, #000); } .frk-keycap--rams .frk-keycap__top { background: var(--rams); color: var(--on-rams); }
.frk-keycap--sol { background: color-mix(in srgb, var(--sol) 70%, #000); } .frk-keycap--sol .frk-keycap__top { background: var(--sol); color: var(--on-sol); }
.frk-keycap--klein { background: color-mix(in srgb, var(--klein) 70%, #000); } .frk-keycap--klein .frk-keycap__top { background: var(--klein); color: var(--on-klein); }
.frk-keycap--round, .frk-keycap--round .frk-keycap__top { border-radius: var(--radius-full); }

/* Calculator */
.frk-calc { display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-5); border-radius: var(--radius-xl); background: var(--well); max-width: 340px; }
.frk-calc__display { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; padding: var(--space-4); border-radius: var(--radius-md); background: #1b1d17; color: #d7f0a8; min-width: 0; overflow: hidden; }
.frk-calc__expr { font: 500 12px/16px var(--font-mono); color: #a9c27a; min-height: 16px; white-space: nowrap; }
.frk-calc__cur { font: 400 clamp(28px, 9vw, 44px)/1 var(--font-dot); font-variant-numeric: tabular-nums; white-space: nowrap; }
.frk-calc__keys { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: 64px; gap: var(--space-3); }

.frk-calc--round .frk-calc__keys { grid-auto-rows: auto; }
.frk-calc--round .frk-keycap { aspect-ratio: 1; }
.frk-calc--round .frk-keycap[style*="span 2"] { aspect-ratio: auto; border-radius: 40px; }
.frk-calc--round .frk-keycap[style*="span 2"] .frk-keycap__top { border-radius: 36px; }

/* PadGrid */
.frk-pads { display: grid; gap: var(--space-3); padding: var(--space-4); border-radius: var(--radius-lg); background: var(--ink); }
.frk-padkey { aspect-ratio: 1; min-height: 56px; border: 0; border-radius: var(--radius-sm); cursor: pointer; position: relative; display: flex; align-items: flex-end; padding: var(--space-2);
  background: #2b2925; box-shadow: inset 0 0 0 1px rgba(255,255,255,.06); transition: background-color 60ms, transform var(--dur-press, 90ms); touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
.frk-padkey:focus-visible { outline: 2px solid var(--sol); outline-offset: 2px; }
.frk-padkey__lbl { font: 500 10px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: #cfc8bb; }
.frk-padkey.is-hit { transform: scale(.96); }
.frk-pads--sol .frk-padkey.is-hit { background: var(--sol); } .frk-pads--sol .frk-padkey.is-hit .frk-padkey__lbl { color: var(--on-sol); }
.frk-pads--rams .frk-padkey.is-hit { background: var(--rams); } .frk-pads--rams .frk-padkey.is-hit .frk-padkey__lbl { color: var(--on-rams); }
.frk-pads--klein .frk-padkey.is-hit { background: var(--klein); } .frk-pads--klein .frk-padkey.is-hit .frk-padkey__lbl { color: var(--on-klein); }
html[data-theme="dark"] .frk-pads { background: #000; }

/* TapeDeck */
.frk-tape { display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-4); border-radius: var(--radius-xl); background: var(--surface); box-shadow: inset 0 0 0 1px var(--line); max-width: 420px; }
.frk-tape__head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--space-3); }
.frk-tape__title { font: 700 14px/18px var(--font-sans); }
.frk-tape__count { font: 400 24px/1 var(--font-dot); font-variant-numeric: tabular-nums; }
.frk-tape svg { display: block; }
.frk-tape__ring { fill: var(--well); }
.frk-tape__wound { fill: var(--tabaco); transition: r 1s linear; }
.frk-tape__hub { fill: var(--surface); }
.frk-tape__spoke { fill: var(--ink); }
.frk-tape__belt { fill: none; stroke: var(--tabaco); stroke-width: 3; }
.frk-tape__headblock { fill: var(--ink); }
.frk-tape__reel { transform-box: view-box; }
.frk-tape__reel.is-spin { animation: frk-spin 1.4s linear infinite; }
@keyframes frk-spin { to { transform: rotate(360deg); } }
.frk-tape__prog { height: 4px; border-radius: 2px; background: var(--well); overflow: hidden; }
.frk-tape__prog > span { display: block; height: 100%; background: var(--ink); }

/* Board / Sortable */
.frk-board { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: var(--space-4); align-items: start; position: relative; }
.frk-board.is-dragging { cursor: grabbing; user-select: none; }
.frk-board--list { grid-template-columns: 1fr; max-width: 420px; }
.frk-col { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-2); border-radius: var(--radius-lg); background: var(--well); transition: box-shadow var(--dur-fast, 150ms); min-width: 0; }
.frk-col.is-over { box-shadow: inset 0 0 0 2px var(--klein); }
.frk-board--list .frk-col { background: transparent; padding: 0; }
.frk-col__head { display: flex; align-items: center; gap: var(--space-2); padding: 4px 6px; }
.frk-col__title { font: 700 14px/18px var(--font-sans); flex: 1; }
.frk-col__count { font: 500 11px/14px var(--font-mono); color: var(--ink-muted); }
.frk-col__list { display: flex; flex-direction: column; gap: var(--space-2); min-height: 56px; }
.frk-col__empty { display: grid; place-items: center; min-height: 64px; border-radius: var(--radius-md); border: 1.5px dashed var(--ink-muted); font: 500 11px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-card-dnd { display: flex; align-items: center; gap: var(--space-3); min-height: 56px; padding: 10px 12px 10px 8px; border-radius: var(--radius-md); background: var(--surface); color: var(--ink);
  box-shadow: 0 1px 0 var(--line); cursor: grab; touch-action: none; user-select: none; transition: opacity var(--dur-fast, 150ms), box-shadow var(--dur-fast, 150ms), transform var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-card-dnd:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.frk-card-dnd__grip { color: var(--ink-muted); display: inline-flex; transform: rotate(90deg); }
.frk-card-dnd__body { display: flex; flex-direction: column; gap: 2px; flex: 1; min-width: 0; }
.frk-card-dnd__title { font: 600 15px/20px var(--font-sans); overflow-wrap: anywhere; }
.frk-card-dnd__meta { font: 500 11px/14px var(--font-mono); color: var(--ink-muted); }
.frk-card-dnd.is-ghost { opacity: .35; }
.frk-card-dnd.is-held { box-shadow: 0 0 0 2px var(--klein), 0 10px 24px rgba(0,0,0,.14); transform: scale(1.02); }
.frk-card-dnd.is-floating { position: fixed; left: 0; top: 0; z-index: 50; pointer-events: none; box-shadow: 0 16px 32px rgba(0,0,0,.2); cursor: grabbing; }
.frk-dropline { height: 4px; border-radius: 2px; background: var(--klein); position: relative; margin: -2px 0; }
.frk-dropline::before, .frk-dropline::after { content: ''; position: absolute; top: -3px; width: 10px; height: 10px; border-radius: var(--radius-full); background: var(--klein); }
.frk-dropline::before { left: -4px; } .frk-dropline::after { right: -4px; }

/* Blueprint */
.frk-bp { position: relative; overflow: hidden; border-radius: var(--radius-lg); background: var(--surface); box-shadow: inset 0 0 0 1px var(--line); --bp-dot: color-mix(in srgb, var(--ink) 28%, transparent); --bp-major: color-mix(in srgb, var(--klein) 22%, transparent); --bp-ink: var(--klein-ink); }
html[data-theme="dark"] .frk-bp { --bp-ink: #8fb0ff; }
.frk-bp__canvas { position: absolute; inset: 24px 0 0 24px; cursor: grab; touch-action: none;
  background-image: radial-gradient(circle, var(--bp-dot) 1px, transparent 1.4px), linear-gradient(to right, var(--bp-major) 1px, transparent 1px), linear-gradient(to bottom, var(--bp-major) 1px, transparent 1px); }
.frk-bp.is-note .frk-bp__canvas { cursor: crosshair; }
.frk-bp__canvas:active { cursor: grabbing; }
.frk-bp__world { position: absolute; left: 0; top: 0; transform-origin: 0 0; }
.frk-bp__edges { position: absolute; left: 0; top: 0; pointer-events: none; }
.frk-bp__edge { fill: none; stroke: var(--bp-ink); stroke-width: 1.5; }
.frk-bp__arrowhead { fill: var(--bp-ink); }
.frk-bp__elabel { font: 500 10px var(--font-mono); letter-spacing: .06em; fill: var(--bp-ink); text-transform: uppercase; }
.frk-bp__dims line { stroke: var(--rams); stroke-width: 1; }
.frk-bp__dims text { font: 600 10px var(--font-mono); fill: var(--rams); }
html:not([data-theme="dark"]) .frk-bp__dims text { fill: #a3400c; }
.frk-bp__node { position: absolute; box-sizing: border-box; display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border-radius: 4px; cursor: move; touch-action: none; user-select: none;
  box-shadow: inset 0 0 0 1.5px var(--ink); }
.frk-bp__node.frk-tone--surface { background: color-mix(in srgb, var(--surface) 92%, transparent); }
.frk-bp__node.is-circle { border-radius: var(--radius-full); justify-content: center; align-items: center; text-align: center; }
.frk-bp__node.is-sel { box-shadow: inset 0 0 0 1.5px var(--ink), 0 0 0 2px var(--klein); }
.frk-bp__node:focus-visible { outline: 2px solid var(--focus); outline-offset: 4px; }
.frk-bp__ntitle { font: 700 12px/15px var(--font-sans); }
.frk-bp__ntext { font: 500 10px/13px var(--font-mono); opacity: .85; }
.frk-bp__handle { position: absolute; width: 8px; height: 8px; background: var(--surface); box-shadow: inset 0 0 0 1.5px var(--klein); border-radius: 1px; }
.frk-bp__handle--0 { left: -4px; top: -4px; } .frk-bp__handle--1 { right: -4px; top: -4px; } .frk-bp__handle--2 { right: -4px; bottom: -4px; } .frk-bp__handle--3 { left: -4px; bottom: -4px; }
.frk-bp__ruler { position: absolute; background: var(--surface); overflow: hidden; }
.frk-bp__ruler line { stroke: var(--ink-muted); stroke-width: 1; }
.frk-bp__ruler text { font: 500 9px var(--font-mono); fill: var(--ink-muted); }
.frk-bp__ruler--x { left: 24px; top: 0; right: 0; height: 24px; width: calc(100% - 24px); box-shadow: inset 0 -1px 0 var(--line); }
.frk-bp__ruler--y { left: 0; top: 24px; bottom: 0; width: 24px; height: calc(100% - 24px); box-shadow: inset -1px 0 0 var(--line); }
.frk-bp__corner { position: absolute; left: 0; top: 0; width: 24px; height: 24px; display: grid; place-items: center; font: 600 9px var(--font-mono); color: var(--ink-muted); background: var(--surface); box-shadow: inset -1px -1px 0 var(--line); }
.frk-bp__ui { position: absolute; z-index: 2; }
.frk-bp__tools { right: 16px; top: 40px; }
.frk-bp__zoom { right: 16px; bottom: 16px; display: flex; gap: 4px; padding: 4px; border-radius: var(--radius-full); background: var(--ink); }
.frk-bp__zoom button { min-width: 44px; height: 44px; border: 0; border-radius: var(--radius-full); background: transparent; color: var(--paper); cursor: pointer; display: grid; place-items: center; font: 600 12px var(--font-mono); }
.frk-bp__zoom button:hover { background: color-mix(in srgb, var(--paper) 14%, transparent); }
.frk-bp__zoom button:focus-visible { outline: 2px solid var(--sol); outline-offset: 1px; }
.frk-bp__hud { left: 40px; bottom: 16px; padding: 6px 10px; border-radius: var(--radius-sm); background: var(--ink); color: var(--paper); font: 500 11px/14px var(--font-mono); letter-spacing: .04em; font-variant-numeric: tabular-nums; pointer-events: none; }

/* Gráficas: área, dispersión, radar, donut, osciloscopio */
.frk-area, .frk-scatter, .frk-radar, .frk-donut, .frk-scope { margin: 0; display: flex; flex-direction: column; gap: var(--space-3); }
.frk-area svg, .frk-scatter svg, .frk-radar svg, .frk-scope svg { display: block; overflow: visible; max-width: 100%; height: auto; }
.frk-area__grid { stroke: var(--line); stroke-dasharray: 1 5; stroke-linecap: round; }
.frk-area__line { fill: none; stroke-width: 2.5; stroke-linecap: round; }
.frk-area__dot { stroke: none; }
.frk-area__fill { opacity: .9; }
.frk-area--ink { fill: var(--ink); stroke: var(--ink); }
.frk-area--rams { fill: var(--rams); stroke: var(--rams); }
.frk-area--klein { fill: var(--klein); stroke: var(--klein); }
.frk-area--sol { fill: var(--sol); stroke: var(--sol); }
.frk-area--verde { fill: var(--verde); stroke: var(--verde); }
.frk-area--tabaco { fill: var(--tabaco); stroke: var(--tabaco); }
.frk-area__line.frk-area--ink, .frk-area__line.frk-area--rams, .frk-area__line.frk-area--klein, .frk-area__line.frk-area--sol, .frk-area__line.frk-area--verde, .frk-area__line.frk-area--tabaco { fill: none; }
.frk-scatter__grid { fill: var(--ink-faint); }
.frk-scatter__axis { stroke: var(--ink); stroke-width: 1; }
.frk-scatter__pt { stroke: var(--surface); stroke-width: 2; }
.frk-radar__axis { stroke: var(--line); }
.frk-radar__shape { fill-opacity: .18; stroke-width: 2; stroke-linejoin: round; }
.frk-donut__wrap { position: relative; }
.frk-donut__seg { fill: none; stroke-linecap: round; }
.frk-donut__seg.frk-area--ink { fill: none; } .frk-donut__seg[class*="frk-area--"] { fill: none; }
.frk-donut__center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.frk-donut__value { font: 400 40px/1 var(--font-dot); font-variant-numeric: tabular-nums; }
.frk-donut__cap { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
.frk-donut .frk-split__legend b { font-family: var(--font-mono); font-weight: 700; margin-left: 2px; }
.frk-scope svg { background: #12140f; border-radius: var(--radius-md); }
.frk-scope__grid { fill: #3c4a2c; }
.frk-scope__trace { fill: none; stroke: #b6f03c; stroke-width: 2; stroke-linejoin: round; filter: drop-shadow(0 0 3px rgba(182,240,60,.55)); }
.frk-scope__cap { display: flex; justify-content: space-between; gap: var(--space-3); font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }

/* VoicePosition */
.frk-vpos { display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-5); border-radius: var(--radius-xl); background: var(--ink); color: var(--paper); max-width: 440px; --vp: var(--klein); --ink-muted: color-mix(in srgb, var(--paper) 72%, var(--ink)); }
.frk-vpos--rams { --vp: var(--rams); } .frk-vpos--sol { --vp: var(--sol); } .frk-vpos--verde { --vp: #4fb07a; }
html[data-theme="dark"] .frk-vpos { background: #000; color: #f1ece2; --ink-muted: #c9c1b3; }
.frk-vpos--klein { --vp: #5b84ff; }
.frk-vpos__stage svg { display: block; overflow: visible; }
.frk-vpos__body { transition: transform var(--dur-grow, 640ms) var(--ease-travel, cubic-bezier(.65,0,.35,1)); }
.frk-vpos__dot { fill: color-mix(in srgb, currentColor 55%, transparent); }
.frk-vpos__dot.is-outer { fill: var(--vp); }
.frk-vpos.is-idle .frk-vpos__dot.is-outer { fill: color-mix(in srgb, currentColor 40%, transparent); }
.frk-vpos__dot.is-hi { fill: var(--sol); }
.frk-vpos__core { fill: var(--vp); transition: fill var(--dur-base, 220ms), r var(--dur-base, 220ms); }
.frk-vpos.is-idle .frk-vpos__core { fill: color-mix(in srgb, currentColor 22%, transparent); }
.frk-vpos.is-processing .frk-vpos__core { fill: var(--sol); }
.frk-vpos__scale { fill: color-mix(in srgb, currentColor 45%, transparent); }
.frk-vpos__cursor { fill: var(--vp); transition: cx var(--dur-grow, 640ms) var(--ease-travel, ease-in-out), opacity var(--dur-base, 220ms); }
.frk-vpos__cursor.is-off { opacity: 0; }
.frk-vpos__read { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-2); }
.frk-vpos__cell { display: flex; flex-direction: column; gap: var(--space-1); padding: var(--space-3); border-radius: var(--radius-md); background: color-mix(in srgb, currentColor 9%, transparent); transition: background-color var(--dur-base, 220ms), color var(--dur-base, 220ms); min-width: 0; }
.frk-vpos__cell.is-on { background: var(--paper); color: var(--ink); --ink-muted: var(--ink); }
html[data-theme="dark"] .frk-vpos__cell.is-on { background: #f1ece2; color: #1b1915; --ink-muted: #1b1915; }
.frk-vpos__bars { display: flex; gap: 3px; height: 8px; }
.frk-vpos__bars > span { width: 8px; height: 8px; border-radius: var(--radius-full); background: color-mix(in srgb, currentColor 25%, transparent); transition: background-color var(--dur-base, 220ms); }
.frk-vpos__bars > span.is-on { background: currentColor; }
.frk-vpos__cell.is-on .frk-vpos__bars > span.is-on { background: var(--klein); }
.frk-vpos__lbl { font: 500 10px/12px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.frk-vpos__pct { font: 700 16px/18px var(--font-mono); font-variant-numeric: tabular-nums; }
.frk-vpos__distmark { height: 8px; display: flex; align-items: center; }
.frk-vpos__distmark > span { width: 8px; height: 8px; border-radius: var(--radius-full); background: currentColor; transition: width var(--dur-base, 220ms), height var(--dur-base, 220ms); }
.frk-vpos__dist.is-far .frk-vpos__distmark > span { width: 4px; height: 4px; }
.frk-vpos__foot { display: flex; justify-content: space-between; align-items: center; gap: var(--space-3); flex-wrap: wrap; }
.frk-vpos .frk-led__text { color: inherit; }
.frk-vpos__note { font: 500 10px/14px var(--font-mono); letter-spacing: .06em; color: var(--ink-muted); }
@media (max-width: 360px) { .frk-vpos__read { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

@media (prefers-reduced-motion: reduce) {
  .frk-tape__reel.is-spin { animation: none; }
  .frk-vpos__body, .frk-vpos__cursor, .frk-rotary__bar, .frk-card-dnd, .frk-vu__needle, .frk-fader__cap { transition-duration: 1ms !important; }
  .frk-keycap:active, .frk-padkey.is-hit { transform: none; }
}

/* Beam */
.frk-beam { position: relative; }
.frk-beam__svg { position: absolute; left: 0; top: 0; pointer-events: none; overflow: visible; }
.frk-beam__svg rect { fill: none; stroke-linecap: round; }
.frk-beam__track { stroke: transparent; stroke-width: 3; stroke-dasharray: 0 8; transition: stroke var(--dur-base, 220ms); }
.frk-beam.is-on .frk-beam__track { stroke: color-mix(in srgb, var(--beam) 30%, transparent); }
.frk-beam__head, .frk-beam__tail { stroke: var(--beam); stroke-width: 3; animation: frk-beam 2.4s linear infinite; }
.frk-beam__head { stroke-width: 4; }
.frk-beam__tail { stroke-width: 4; animation-delay: -1.2s; opacity: .45; }
@keyframes frk-beam { from { stroke-dashoffset: var(--per, 1000); } to { stroke-dashoffset: 0; } }
.frk-beam--klein { --beam: var(--klein); } .frk-beam--rams { --beam: var(--rams); } .frk-beam--sol { --beam: var(--sol); } .frk-beam--ink { --beam: var(--ink); }
html[data-theme="dark"] .frk-beam--klein { --beam: #5b84ff; }
@media (prefers-reduced-motion: reduce) { .frk-beam__head, .frk-beam__tail { animation: none; } .frk-beam__tail { display: none; } }

/* Aura: disponible = un halo que respira, no un puntito en la esquina */
.frk-aura { --aura: var(--verde); border-radius: var(--radius-full); }
.frk-aura--rect { border-radius: var(--radius-lg); }
span.frk-aura:not(.frk-avatar) { display: inline-flex; }
.frk-aura--verde { --aura: #2f9d62; } .frk-aura--rec { --aura: var(--rec); } .frk-aura--sol { --aura: var(--sol); } .frk-aura--rams { --aura: var(--rams); } .frk-aura--klein { --aura: var(--klein); }
html[data-theme="dark"] .frk-aura--klein { --aura: #5b84ff; }
.frk-aura.is-on { animation: frk-aura 3.2s var(--ease-travel, ease-in-out) infinite;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--aura) 30%, transparent), 0 0 24px 8px color-mix(in srgb, var(--aura) 32%, transparent); }
.frk-aura.is-fast { animation-duration: 1.4s; }
@keyframes frk-aura {
  0%, 100% { box-shadow: 0 0 0 4px color-mix(in srgb, var(--aura) 30%, transparent), 0 0 24px 8px color-mix(in srgb, var(--aura) 32%, transparent); }
  50% { box-shadow: 0 0 0 9px color-mix(in srgb, var(--aura) 16%, transparent), 0 0 48px 20px color-mix(in srgb, var(--aura) 34%, transparent); } }
.frk-avatar.is-offline { background: var(--well) !important; box-shadow: inset 0 0 0 2px var(--line); }
.frk-avatar.is-offline, .frk-avatar.is-offline > span { --ink-muted: initial; color: var(--ink) !important; }

/* DotGrid para elegir: plazas, días, horas */
.frk-dotgrid--pick { display: inline-flex; flex-direction: column; gap: var(--space-4); }
.frk-dotgrid__grid { display: grid; }
.frk-dotgrid--pick .frk-dotgrid__dot { position: relative; border: 0; padding: 0; cursor: pointer; display: grid; place-items: center; background: var(--surface); color: var(--ink);
  box-shadow: inset 0 0 0 2px var(--line); -webkit-tap-highlight-color: transparent;
  transition: transform var(--dur-base, 220ms) var(--ease-arrive, ease-out), background-color var(--dur-fast, 150ms), box-shadow var(--dur-fast, 150ms), color var(--dur-fast, 150ms); }
.frk-dotgrid--pick .frk-dotgrid__dot.is-near { transform: scale(1.06); }
.frk-dotgrid--pick .frk-dotgrid__dot.is-hover { transform: scale(1.16); box-shadow: inset 0 0 0 2px var(--ink); }
.frk-dotgrid--pick .frk-dotgrid__dot:active:not(.is-taken) { transform: scale(.92); transition-duration: var(--dur-press, 90ms); }
.frk-dotgrid--pick .frk-dotgrid__dot:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
.frk-dotgrid--pick .frk-dotgrid__dot.is-on { background: var(--pick); color: var(--on-pick); box-shadow: none; animation: frk-pop var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-dotgrid--pick .frk-dotgrid__dot.is-taken { cursor: not-allowed; background: var(--well); box-shadow: none; color: var(--ink-faint); }
.frk-dotgrid--pick .frk-dotgrid__dot.is-taken::after { content: ''; width: 34%; height: 2px; border-radius: 1px; background: var(--ink-muted); transform: rotate(-45deg); position: absolute; }
.frk-dotgrid--klein { --pick: var(--klein); --on-pick: var(--on-klein); } .frk-dotgrid--rams { --pick: var(--rams); --on-pick: var(--on-rams); } .frk-dotgrid--ink { --pick: var(--ink); --on-pick: var(--paper); } .frk-dotgrid--sol { --pick: var(--sol); --on-pick: var(--on-sol); } .frk-dotgrid--verde { --pick: var(--verde); --on-pick: var(--on-verde); }
.frk-dotgrid__lbl { font: 600 13px/1 var(--font-mono); font-variant-numeric: tabular-nums; }
.frk-dotgrid__cap { font: 500 11px/14px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-muted); }
@keyframes frk-pop { 0% { transform: scale(.8); } 60% { transform: scale(1.12); } 100% { transform: scale(1); } }

/* SplitFlap: tonos + panel */
.frk-flap--sol .frk-flap__cell { background: var(--sol); color: #16140f; }
.frk-flap--rams .frk-flap__cell { background: var(--rams); color: #16140f; }
.frk-flap--verde .frk-flap__cell { background: var(--verde); color: var(--on-verde); }
.frk-flap--rec .frk-flap__cell { background: var(--rec); color: var(--on-rec); }
.frk-flapboard { display: inline-flex; flex-direction: column; gap: var(--space-2); padding: var(--space-5); border-radius: var(--radius-xl); background: #0b0b0a; color: #f2f0ea; max-width: 100%; box-sizing: border-box; min-width: 0; }
.frk-flapboard__grid { overflow-x: auto; max-width: 100%; padding-bottom: 2px; position: relative; }
.frk-flap { position: relative; }
.frk-flapboard__title { display: flex; justify-content: space-between; gap: var(--space-4); font: 700 14px/18px var(--font-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--sol); padding-bottom: 8px; }
.frk-flapboard__grid { display: grid; column-gap: var(--space-4); row-gap: var(--space-2); align-items: center; }
.frk-flapboard__head, .frk-flapboard__row { display: contents; }
.frk-flapboard__head span { font: 500 10px/12px var(--font-mono); letter-spacing: .1em; text-transform: uppercase; color: #bdb6aa; }
@media (prefers-reduced-motion: reduce) { .frk-aura.is-on { animation: none; } .frk-dotgrid--pick .frk-dotgrid__dot { transition-duration: 1ms !important; } .frk-dotgrid--pick .frk-dotgrid__dot.is-on { animation: none; } }

/* ================= Detalle fino: microinteracciones de toda la librería =================
   Reglas: todo en 90–380 ms, nada se mueve más de 2 px salvo lo que viaja, las sombras son pequeñas
   y cercanas (luz cenital), y con movimiento reducido solo quedan los cambios de color. */

/* 1. El anillo de foco no aparece: se cierra sobre la pieza desde 8 px */
@keyframes frk-focus-in { from { outline-offset: 8px; outline-color: transparent; } }
:is(button, a[href], input, textarea, select, [role=button], [role=slider], [role=tab], [role=radio], [role=switch], [role=checkbox], [role=option], [tabindex="0"]):focus-visible { animation: frk-focus-in var(--dur-base, 220ms) var(--ease-arrive, ease-out); }

/* 2. Teclas: con ratón, se levantan 1 px y su sombra se abre; al pulsar se hunden y la sombra se recoge */
@media (hover: hover) {
  .frk-key:hover:not(:disabled):not(:active), .frk-keycap:hover:not(:active) { transform: translateY(-1px); box-shadow: var(--shadow-lift); }
  .frk-keycap:hover:not(:active) { box-shadow: 0 4px 0 rgba(0,0,0,.18), 0 10px 18px -12px rgba(0,0,0,.5); }
  button.frk-tile:hover, .frk-card-dnd:hover:not(.is-held):not(.is-ghost), .frk-choice:hover { box-shadow: 0 1px 1px rgba(0,0,0,.05), 0 12px 24px -16px rgba(0,0,0,.45); transform: translateY(-1px); }
  button.frk-row:hover { background: linear-gradient(to right, var(--well), var(--well)) no-repeat 0 0 / 100% 100%; }
  .frk-input:hover { box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--ink) 16%, transparent); }
  .frk-dial__knob:hover { box-shadow: 0 0 0 6px color-mix(in srgb, var(--ink) 8%, transparent); }
  .frk-slider:hover .frk-slider__thumb { transform: scale(1.18); box-shadow: 0 0 0 8px color-mix(in srgb, var(--rams) 18%, transparent); }
  .frk-padkey:hover:not(.is-hit) { box-shadow: inset 0 0 0 1px rgba(255,255,255,.16); }
  .frk-bp__node:hover:not(.is-sel) { box-shadow: inset 0 0 0 1.5px var(--ink), 0 0 0 4px color-mix(in srgb, var(--klein) 14%, transparent); }
}
button.frk-tile, .frk-choice, button.frk-row { transition: transform var(--dur-base, 220ms) var(--ease-arrive, ease-out), box-shadow var(--dur-base, 220ms) var(--ease-arrive, ease-out), background-color var(--dur-fast, 150ms); }
button.frk-tile:active, .frk-choice:active { transform: translateY(0) scale(.99); box-shadow: var(--shadow-press); transition-duration: var(--dur-press, 90ms); }
.frk-dial__knob { transition: box-shadow var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-slider__thumb { transition: transform var(--dur-fast, 150ms) var(--ease-settle, cubic-bezier(.22,1,.36,1)), box-shadow var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-slider:active .frk-slider__thumb { transform: scale(1.3); }

/* 3. Campos: al enfocar, el borde se dibuja desde dentro y el fondo se aclara */
.frk-input { transition: background-color var(--dur-fast, 150ms) var(--ease-ui, ease-out), box-shadow var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-input:focus-visible { box-shadow: inset 0 0 0 1.5px var(--ink); }

/* 4. Casilla: el ✓ se traza, no aparece */
@keyframes frk-draw { from { stroke-dashoffset: 26; } to { stroke-dashoffset: 0; } }
.frk-check.is-on .frk-check__box .frk-icon :is(path, polyline, line) { stroke-dasharray: 26; animation: frk-draw var(--dur-base, 220ms) var(--ease-arrive, ease-out); }
.frk-check__box { transition: background-color var(--dur-fast, 150ms), color var(--dur-fast, 150ms), transform var(--dur-press, 90ms) var(--ease-ui, ease-out), box-shadow var(--dur-base, 220ms); }
.frk-check:hover:not(.is-disabled) .frk-check__box { box-shadow: 0 0 0 5px color-mix(in srgb, var(--ink) 8%, transparent); }

/* 5. Hover = un paso del propio color, nunca un cambio a gris (en oscuro, un paso más claro) */
:root { --hover-mix: #000; --hover-step: 6%; } html[data-theme="dark"] { --hover-mix: #fff; --hover-step: 8%; }
@media (hover: hover) {
  :is(.frk-key, .frk-keypad__key)[class*="frk-tone--"]:hover:not(:disabled):not(.is-active) { background: color-mix(in srgb, var(--tone-bg), var(--hover-mix) var(--hover-step)); }
}

/* 6. Popovers, menús, hojas y toasts: sombra corta y cercana, nunca un halo gris */
.frk-pop, .frk-menu__list, .frk-toast { box-shadow: var(--shadow-float); }

/* 7. Arrastre: lo que se coge se levanta, lo que queda detrás se hunde */
.frk-card-dnd.is-floating { box-shadow: 0 2px 4px rgba(0,0,0,.08), 0 22px 40px -18px rgba(0,0,0,.5); will-change: transform; }
.frk-card-dnd.is-ghost { box-shadow: inset 0 0 0 1.5px var(--line); background: transparent; }

@media (prefers-reduced-motion: reduce) {
  :is(button, a[href], input, textarea, select, [role], [tabindex="0"]):focus-visible { animation: none; }
  .frk-key:hover, .frk-keycap:hover, button.frk-tile:hover, .frk-card-dnd:hover, .frk-choice:hover { transform: none !important; }
  .frk-switch__dot, .frk-switch__text, .frk-seg__thumb { transition-duration: 1ms !important; }
  .frk-check.is-on .frk-check__box .frk-icon * { animation: none; }
}

/* ---------- Contenedores estrechos: ningún componente se sale de su caja ---------- */
.frk-seg, .frk-tabbar { max-width: 100%; overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: none; }
.frk-seg::-webkit-scrollbar, .frk-tabbar::-webkit-scrollbar { display: none; }
.frk-seg__opt, .frk-tabbar__item { flex: none; }
.frk-readout--hero .frk-readout__value { font-size: clamp(56px, 24vw, 120px); }
.frk-readout--display .frk-readout__value { font-size: clamp(40px, 15vw, 64px); }
.frk-watch { min-width: min(280px, 100%); max-width: 100%; }
.frk-timer, .frk-pendulum, .frk-notch--inline, .frk-note, .frk-audio, .frk-beam, .frk-tile, .frk-reveal__item, .frk-flap, .frk-flap__cells { min-width: 0; max-width: 100%; }
.frk-pendulum__ctrl { flex-wrap: wrap; justify-content: center; row-gap: var(--space-3); }
.frk-flap__cells { flex-wrap: wrap; row-gap: 3px; }
.frk-note__title { width: 100%; min-width: 0; }
.frk-composer__input { min-width: 0; width: 100%; }
@media (max-width: 420px) { .frk-pad { padding: var(--space-4); } }
.frk-notch--inline { width: min(240px, 100%); }
.frk-notch--inline.is-open { width: min(440px, 100%); }
.frk-note__input { field-sizing: content; }
.frk-note__title { font-size: clamp(26px, 9vw, 36px); }

}

/* Frekvens para Tailwind v4: importa este archivo después de "tailwindcss" y tendrás bg-klein, text-ink, rounded-xl, ease-settle… */
@import "./tokens.css";
@theme inline {
  --color-paper: var(--paper);
  --color-surface: var(--surface);
  --color-well: var(--well);
  --color-dot-off: var(--dot-off);
  --color-line: var(--line);
  --color-ink: var(--ink);
  --color-ink-muted: var(--ink-muted);
  --color-ink-faint: var(--ink-faint);
  --color-klein: var(--klein);
  --color-on-klein: var(--on-klein);
  --color-klein-ink: var(--klein-ink);
  --color-klein-soft: var(--klein-soft);
  --color-sol: var(--sol);
  --color-on-sol: var(--on-sol);
  --color-rams: var(--rams);
  --color-on-rams: var(--on-rams);
  --color-tabaco: var(--tabaco);
  --color-on-tabaco: var(--on-tabaco);
  --color-salvia: var(--salvia);
  --color-lavanda: var(--lavanda);
  --color-malva: var(--malva);
  --color-verde: var(--verde);
  --color-on-verde: var(--on-verde);
  --color-rec: var(--rec);
  --color-on-rec: var(--on-rec);
  --color-focus: var(--focus);
  --radius-0: var(--radius-0);
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-full: var(--radius-full);
  --font-sans: var(--font-sans);
  --font-dot: var(--font-dot);
  --font-mono: var(--font-mono);
  --ease-ui: var(--ease-ui);
  --ease-arrive: var(--ease-arrive);
  --ease-travel: var(--ease-travel);
  --ease-throw: var(--ease-throw);
  --ease-exit: var(--ease-exit);
  --ease-settle: var(--ease-settle);
  --ease-press: var(--ease-press);
  --duration-press: var(--dur-press);
  --duration-fast: var(--dur-fast);
  --duration-base: var(--dur-base);
  --duration-sheet: var(--dur-sheet);
  --duration-grow: var(--dur-grow);
  --shadow-none: var(--shadow-none);
  --shadow-press: var(--shadow-press);
  --shadow-lift: var(--shadow-lift);
  --shadow-float: var(--shadow-float);
}
